import type { TlumPsalms } from './index';
// Кафизма 16: псалми 109–117.
export const Z: TlumPsalms = {"109":[{"v":"0","t":["Псалом Давидів.","Про цей напис ми говорили багато разів. Цей псалом стосується Христа.","Прим.: Феодорит зауважує, що Сам Господь в Євангелії відніс цей псалом до Себе; так Він, запитуючи фарисеїв, сказав: що ви думаєте про Христа? Чий Він син? Кажуть Йому: Давидів. Каже їм: як же Давид у Дусі називає Його Господом, кажучи: сказав Господь Господеві моєму: сядь праворуч Мене, доки покладу ворогів Твоїх у підніжжя ніг Твоїх? Отже, якщо Давид називає Його Господом, то як же Він син його? І ніхто не міг відповісти Йому ні слова (Мт. 22:42–46). Бо фарисеї визнавали Христа сином Давида, а що Він був Господом Давида (тобто за Божеством), того зовсім не знали. Тому Господь додає те, чого бракувало, не відкидаючи того, що визнавалося, а навчаючи, що той самий є Сином Давида за плоттю й водночас його Господом, як Бог і Творець. Тож нехай скажуть юдеї, що відносять цей псалом до Авраама, ніби від імені раба, і аріани та євноміани, що відносять його до Бога Слова до часу Його втілення, і павліани, савеліани й фотиніани, що відносять його до Христа як простої людини: що вони можуть сказати на ці слова: з утроби перед денницею Я народив Тебе? Слова Афанасія: цей псалом пророкує про народження Господа за плоттю й Його вознесіння на небеса."]},{"v":"1","t":["Бог, каже, Отець сказав до Бога, Свого Сина, після вознесіння Його на небо. А якщо й написано: Господь Бог наш — Господь єдиний, то це написано зовсім не для відкидання Єдинородного, а для розрізнення й відокремлення Його від нікчемних богів. А слова «сказав Господь», тобто Отець до Сина, ми маємо розуміти так, як личить Богові, а не людині, — богогідно, а не по-людськи. Ці слова закривають юдеям уста, бо вони зовсім не знають, що сказати на те, які два Господи в Давида, з яких один народився з утроби перед денницею, тобто зорею. Бо ясно, що це Христос — Бог і людина.","Прим.: Слова Феодорита: якщо Давид — цар, і то цар благочестивий, що сподобився пророчого дару, називає Владику Христа Господом, то Він не тільки проста людина, як безумно твердять юдеї, а й Бог, як Творець і Господь Давида; і спільне Їхнє найменування виражає тотожність Їхньої сутності. Бо Господь каже Господеві — Отець Своєму Синові, а не Господь творінню й не Господь створінню. Інші того, хто говорить, називають Богом, а того, хто слухає, — Зоровавелем. Тож чим буде Зоровавель? Господом Давидовим? І як міг би той, хто сам названий Давидом на віддяку йому за велику честь? Де він мав священство, та ще якесь незвичайне й дивне? Отже, слова «Господь Господеві моєму» сказано про Христа. А в єврейському Псалтирі написано: «сказав Ягве Адонаю моєму», що виражає єдиносутність Отця з Сином, бо жодне творіння не зветься Ягве: це ім'я належить одному Богові й одному божественному й нествореному єству, а не якомусь іншому, створеному єству.","«Сядь праворуч Мене»","Як найменуваннями «Господь» і «Господь» виражається рівночесність Отця з Сином і, навпаки, Сина з Отцем, так і сидінням праворуч на царському престолі показується та сама їхня рівночесність; бо в кого сидіння спільне, у тих і царство спільне. Тож нехай закриються уста Арія та Євномія, що пустословлять, ніби Син не рівний Отцеві. А оскільки безтілесні й неописані не мають правого й лівого боку, що властиво тільки тілам, то сидіння тут означає спокій і насолоду Божим царством, а сидіння праворуч показує справжність синівства Сина, близькість і рівну честь.","Прим.: Слова Василія Великого: бо якщо престол Божий, як ми переконані, — найменування гідності, то окреме для Господа сидіння праворуч Отця що інше може означати, як не рівночесність гідності? І правий бік виражає ставлення до рівного, утім так, що правий бік не слід розуміти тілесно, бо інакше був би й лівий. Але ці слова шанобливими найменуваннями сидіння виражають велич синівської честі. Отже, як з того, що Він займає найпочесніше сидіння праворуч, ми не можемо висновувати, що Він більший за Отця, так і ти не кажи, що Він вищий чи нижчий, а що Він рівночесний і рівний, як це показує й спільне сидіння. Кирила: правий бік означає рівночесність гідності. Севира: під правим боком ми розуміємо рівночесність Сина з Отцем, бо щодо безтілесної сутності не можна уявляти ні правого, ні лівого боку. Те саме каже й Ісихій: а не Сам Син привласнює Собі гідність царства й Божества (тому Павло й каже: не вважав за захоплення бути рівним Богові), а через те, що Отець благоволив до Нього й Син має гідність, Він має царство й рівночесність з Отцем. Отже, престол, за словами Євсевія, означає Його царську гідність; сидіння — непохитність, твердість і незмінність Його перебування на царстві; а «праворуч» означає спільність у благах і правих дарах Отця. Феодорита: велике означає сидіння праворуч, і воно перевершує не тільки людську природу, а й усяке творіння. Утім, і це сказано по-людськи. Бо як Бог Син має вічний престол: престол Твій, каже, Боже, на віки віків. Оскільки не після хреста й страждання Він сподобився такої честі як Бог, а дістав як людина те, що мав як Бог, то як людина Він і приймає запрошення: сядь праворуч Мене; бо як Бог Він має вічну владу. Божественний Василій каже й в іншому місці: що ж? Оскільки сидить праворуч, то й почесніший? Але якби Він мав честь від Самого Себе, тоді був би почесніший; а якщо Він дістав її від Свого Родителя, то це дар Того, Хто дав.","«Доки покладу ворогів Твоїх у підніжжя ніг Твоїх»","За Феодоритом і Афанасієм, під ворогами тут розуміє юдеїв, еллінів, єретиків і бісів; а слово «доки» не завжди відокремлюється від майбутнього часу, а часто означає «до певного часу», а решта часу не відкидається, а разом з ним мається на увазі, як ось тут; про це й Григорій Богослов любомудрствував у першому слові про Сина, і ми, ідучи за отцями, пояснили слова євангелиста Матвія: доки Вона не народила Сина Свого первістка (Мт. 1:25). Бо якби Христове царство було обмежене тільки певним часом, а не було вічне, то як би виконалося Даниїлове слово: і царство Його — царство вічне (Дан. 7:27); а також: поставить Бог небесний царство, яке не розпадеться повіки (Дан. 2:44)? Або як виявиться правдою те, що сказав Гавриїл Діві: і царству Його не буде кінця (Лк. 1:33)? А коли чуєш, читачу, тут, що Отець кладе ворогів у підніжжя ніг Свого Сина, а в Павла — що Сам Син кладе їх у Своє підніжжя: бо Йому, каже, належить царювати, доки не покладе всіх ворогів під ноги Свої (1 Кор. 15:25), — чуючи, кажу, це, не бентежся, бо дія й сила обох, і Отця, і Сина, однакові, і діла їх обох спільні. Бо всі підкоряться Синові, одні добровільно, а інші мимоволі, коли побачать Його, що сходить з небес у Своєму другому пришесті; про це ясніше навчає Павло, кажучи: щоб перед іменем Господа схилилося всяке коліно небесних, і земних, і підземних (Флп. 2:10). Нарешті підніжжям позначає підкорених, кажучи майже так: доки не покладу ворогів Твоїх підкореними ногам Твоїм.","Прим.: Феодорита: отже, слово «доки» не означає часу, але це властивість божественного Писання, наприклад: доки ви не постарієте, Я є (Іс. 46:4). Очевидно, що буття Боже не обмежується старістю людей, а Творець усіх продовжуватиме Своє буття й після того, як вони постаріють і помруть. Золотоустого: чуючи, як пророк каже, що Отець кладе під ноги, не бентежся; бо це сказано не тому, що Син безсилий, адже Павло каже, що Він Сам кладе під ноги Свої. Діла Їхні спільні; тому й каже: усе Моє — Твоє, і Твоє — Моє. Євсевія: тепер, каже, царюй у Мене й володій Моєю честю й славою; і хоча вороги Церкви й противники Твого імені винищуються й підкоряються Твоїм ногам повільно, але буде час, коли приймеш царство над усім. Ісихія: у цьому житті і Отець підкоряє Синові людство, і Син підкоряє його Отцеві; а коли скінчиться цей вік і в усьому, що відбувається, усе буде Бог, тоді, прийшовши до досконалості споглядання й пізнання, ми побачимо Отця в Сині й Сина в Отці; тому й Господь казав, що тоді прийде Він у славі Отця."],"h":"Сказав Господь Господеві моєму"},{"v":"2","t":["Жезл інколи вживається як знак покарання, як у цьому місці: чого ви хочете? З києм прийти до вас чи з любов'ю й духом лагідності? (1 Кор. 4:21); інколи — як знамення пастирства, як ось тут: пастимеш їх жезлом залізним (Пс. 2:9); інколи — як знак царства, як у таких словах: вийде жезл з кореня Єссеєвого (Іс. 11:1); а інколи — як знак сили, як у цих словах. Пошле, каже, Господь Христові, як людині, силу з Сіону небесного або з Сіону єрусалимського, бо з Сіону почалася сила вишніх діл Христових і проповіді Його Євангелія. Можна також під жезлом сили розуміти й хрест, як розумів і Золотоустий; бо що може бути сильнішим за хрест, який так легко перемагає й проганяє чуттєвих і мисленних ворогів?","Прим.: Феодорита: жезлом сили позначає силу спасенного хреста, бо через нього підкорив усе полчище противників, і на Сіоні його було встановлено. Додаток із Золотоустого: цей жезл хреста навернув землю й море й сповнив їх великою силою. З цим жезлом апостоли, вийшовши в увесь усесвіт, усе це звершили. З ним звершили все, почавши від Єрусалима. Афанасій з Євсевієм під жезлом розумів послане євангельське слово, яке й заволоділо всіма народами. Ісихій: оскільки той жезл має подвійну силу — і карати, і провадити, то й хрест провадить нас і мучить демонів. Отже, влучно він названий і жезлом сили, бо має таку силу. Звідки ж Він послав його? З Сіону, каже, бо там Єдинородний приніс Себе в жертву.","«І пануй посеред ворогів Твоїх»","Пануй, каже, Господи Ісусе Христе, посеред ворогів Твоїх, підкоряючи й упокорюючи їх і ярмом Твоїх євангельських законів привертаючи їх до покори Тобі. Бо дивовижним було те, що божественні апостоли Господні, хоч і були оточені з усіх боків ворогами, однак, за словами Феодорита, перемагали їх, і не просто перемагали, а й підкоряли їх з особливою силою й успіхом.","Прим.: Слова Золотоустого: дивись, яке пророцтво: воно ясніше за сонце. Бо що означає «пануй посеред ворогів Твоїх»? Те саме, що посеред еллінів і юдеїв. Бо як церкви насаджено посеред міст, так вони здобували перевагу й перемогу. Це знак світлої перемоги — поставити жертовники посеред ворогів, овець посеред звірів, ягнят між вовками. До того ж не сказав «перемагай», а «пануй», щоб показати, що торжество звершувалося без війська, а владарювання залежало від повеління. Так здобували владу апостоли, маючи Христа в собі!"],"h":"Жезл сили пошле Тобі Господь із Сіону"},{"v":"3","t":["У той, каже, день, у який відкривається Твоя сила, Господи, тоді буде з Тобою й начальство, тобто буде в Тебе царство, бо воно, за Золотоустим, не дістається Тобі ззовні, а неминуче поєднане з самим Твоїм Божеством. Під начальством можна розуміти й Сина Божого як Причину всього, тобто як Творця, нероздільного з Отцем. А день сили — це день першого явлення Христового і Його незліченних чудес, або день Його другого пришестя, за Феодоритом, і останньої труби, що має пробудити мертвих; бо і перше, і друге пришестя має, за Золотоустим, найбільшу силу.","Прим.: Інший каже: цим позначає час суду, коли Він, прийшовши з ангелами в славі Отця, судитиме кожного. Кирило: і тоді, безперечно, прийде Він, Сам перебуваючи в Отці й маючи в Собі Отця — безпочаткове ніби начало Свого єства, тільки за походженням з Нього, бо Він має буття від Нього. А Ісихій під начальством розуміє хрест Христовий, бо ним переможено князя й царя всесвіту. Так само під днем сили розуміє день хреста (тобто Велику П'ятницю) через знамення й чудеса, що сталися в нього. Бо в цей день Господь мав з Собою начальство, тобто хрест, не тільки тому, що на ньому був прибитий, а й тому, що ніс його на Своїх плечах. Бо ясніше викладаючи це, Ісая казав: Той, Чиє начальство на раменах Його; а пояснюючи це, Григорій Богослов сказав: бо з хрестом підноситься.","«У сяйві святих Твоїх»","Коли, каже, прийде день Твоєї сили й Твого першого пришестя, тоді засяють святі Твої; бо що, за Золотоустим, було світлішим за апостолів, які, обходячи довкола всесвіт, освітлювали його, просвічуючи проповіддю Євангелія й чеснотами, як сонце освітлює всесвіт своїм промінням? А якщо апостоли були такі світлі в перше пришестя Господнє й у цьому віці, то наскільки світлішими вони будуть у Його друге пришестя й у майбутньому віці, коли праведники засяють, як сонце, у Царстві Отця свого (Мт. 13:43), як сказав Господь. Отже, чи приймеш ці слова щодо першого пришестя Господнього, чи щодо другого, — не помилишся, бо і те, й друге, за Золотоустим, покаже найбільшу силу.","Прим.: Слова Афанасія: вислів «у сяйві святих Твоїх» означає не що інше, як лики святих ангелів, що тієї ночі, коли народився Христос, заспівали: Слава во вишніх Богу. Золотоустий сяйвом тут називає красу святих. Бо що світліше за Павла? Що блискучіше за Петра? Вони, обходячи всесвіт, сяяли яскравіше за сонце, коли сяяло насіння благочестя. Бо, мов ангели, що зійшли з неба, вони були неприступні для всіх. Бо ніхто не смів пристати до них, а народ звеличував їх (Діян. 5:13).","«З утроби перед денницею Я народив Тебе»","Слова «сядь праворуч Мене», сказані вище, і слова «з утроби перед денницею Я народив Тебе», сказані тут, мовляться від імені Отця до Сина, як, за словами Дидима, розуміли й усі церковні тлумачі. А слова «жезл сили пошле Тобі Господь» і «з Тобою начало» мовляться від імені Давида до Сина. Слова «з утроби», за Золотоустим, Дидимом і Севиром, означають справжність, а за Феодоритом — тотожність сутності з Отцем. Бо справжні діти народжуються з утроби батьків; і так цим позначається, що Господь — справжній і природний Син Отця, а не смертний і не син за благодаттю, як каже Дидим. Далі слова «перед денницею» означають те саме, що й «перед сонцем», як каже й у 71-му псалмі: перед сонцем перебуває ім'я Його. Що ж це? Невже тільки перед сонцем народив Його Отець? Ні; бо й в іншому місці каже про Нього: і від віку й до віку Ти є (Пс. 89:3), хоча Він не тільки від віку, а й перед віком існує, і не тільки існує до віку, а й понад вік — безкінечно. Отже, такі вислови ми маємо розуміти богогідно, тобто розуміти з них, що Син існує перед усім сущим і що Він предвічний. А ті, хто слова «перед денницею» розуміє про ту ніч, у яку Діва народила Христа, розуміють погано; бо тоді треба було б сказати: перед сходом сонця, а не перед денницею; адже просто «перед сонцем» завжди означає: перед буттям сонця, а «перед сходом сонця», навпаки, означає ранок.","Прим.: Слова Золотоустого: згадав про утробу, щоб цим виразити справжність народження і те, що Син народжений із сутності Отця. І ми також справжнє народження маємо з утроби, а діла робимо руками. Тому утроба й серце означають власність і справжність. Севира: вислів «з утроби народив» означає єдиносутність, а «перед денницею» — предвічність. Феодорита: слово «перед денницею» відкриває, що Він існує перед часами й перед віками, а «з утроби» показує тотожність сутності. Бо не з чогось іншого, каже, а тільки з Моєї природи Ти народився, тож утробу треба сприймати як порівняння. Бо як люди народжують з утроби, і ті, кого вони народжують, мають одну природу з тими, хто їх народив, так і Ти народився від Мене й у Самому Собі показуєш сутність Того, Хто народив. За словами Афанасія, слово «перед денницею» означає, можливо, те, що спосіб народження перебуває в невідомості й незбагненності, ніби в глибокій темряві. Бо яка доречність у тому, щоб представляти Сина народженим перед денницею? Якщо через початок, то чи не краще було б сказати: перед небом і землею? За словами Никити, це «перед денницею» має певним чином ще й такий зміст: Іоан в Одкровенні від імені Христа каже: Я корінь і рід Давидів, зоря світла й досвітня (Одкр. 22:16). Отже, якщо нащадок Давидів — досвітня зоря, то ясно, що денницею назване тілесне народження Спасителя в плоті, перед яким було народження від Бога. Тому сказане тут можна висловити так: Я народив Тебе з Самого Себе перед Твоїм явленням у плоті. Бо «перед денницею» — це те саме, що й «перед втіленням». Слова Євсевія: я дізнався від одного, що римський Псалтир замість «з утроби» має «з Марії», так що ім'я Богородиці згадано ясно; тому дехто каже, що Отець тут приписує Собі тілесне народження Єдинородного, бо Його надприродне народження звершене Його силою; а сказано «перед денницею», бо Господь народився вночі, до ранку. Але це не до вподоби іншим, бо Господь відносить цей псалом не до влаштування плоті, а до народження за Божеством."],"h":"З Тобою начало в день сили Твоєї"},{"v":"4","t":["Як гнів, що приписується Богові, означає не пристрасть, а рух сили, що карає грішників, так і Божа клятва означає утвердження, тобто, за Золотоустим, те, що щось неодмінно має виконатися, а не таку клятву, яка буває в людей. Дієслово «не розкається» означає, що Бог не змінить і не переінакшить того, у чому запевняє, як Він часто робить щодо багатьох речей, змінюючи Свої постанови з інших міркувань для користі, як зауважив Феодорит. У чому ж Він клянеться й що твердо постановляє, про це говорить далі.","Прим.: Афанасія: Божа клятва — це Його слово, що запевняє слухачів і переконує кожного, що обіцяне й сказане Ним виконається. Феодорита: точно пояснив це божественний апостол у Посланні до євреїв, показавши безкінечність цього священства тим, що левитське священство дістало постанови без клятви, а це утверджено клятвою. А сказав це по-людськи, бо Божество не причетне до пристрасті, а розкаяння — теж пристрасть.","«Ти Ієрей повік за чином Мелхиседековим»","Господь був Ієреєм за чином Мелхиседека, бо Він подав апостолам на Таємній вечері хліб і вино, як і Мелхиседек виніс хліб і вино Авраамові й тим, хто був з ним, коли вони поверталися з війни з перемогою над царем Кедорлаомером, як видно з 14-го розділу книги Буття. Христос — Ієрей повік, бо не має, за Божеством, ні початку днів, ні кінця життя, як і Мелхиседек не мав початку й кінця, бо книга Буття про це мовчить. Але Мелхиседек не має цього тому, що історія Писання про це замовчала, не відкривши, від яких батьків він народився й коли помер; а Христос справді не має ні початку, ні кінця.","Прим.: Слова божественного Кирила: за єврейською мовою «мелхі» — цар, «цедек» — правда, а «салим» — мир; і можна бачити, що Мелхиседек був багатий ніби самим своїм найменуванням, а за силою значення слів названий царем правди й миру. Григорія Богослова: отже, Христос зветься Мелхиседеком як безматірній за сутністю, що вища від нашої, як безбатьківський за нашим єством, як той, що не підлягає родоводу за горішнім походженням (бо рід Його, каже, хто розповість?), і як цар Салиму, що означає мир, і як той, хто взяв десятину від патріархів, що відзначилися у війні зі злими силами. Прочитай і 7-й розділ Послання до євреїв, де дивовижний Павло алегорично прикладає історію про Мелхиседека до Христа. Феодорита: Мелхиседек же був священиком не з юдеїв, а з язичників; так і Христос-Владика приніс Самого Себе Богові не тільки за юдеїв, а й за всіх людей. Знаходимо також, що Мелхиседек був і священиком, і царем. Отже, якщо Христос за плоттю від Давида, а Давид від Юди, і священство Він дістав за чином Мелхиседека, то левитське священство вже скінчилося, і благословення вищого священства перейшло до Юдиного коліна. А Христос, що походить від Юди за плоттю, має нині священство не тим, що Сам щось приносить, а тим, що перебуває Головою над тими, хто приносить. Бо Своїм тілом називає Церкву й через неї священнодіє як людина, а приймає те, що вона приносить, як Бог."],"h":"Поклявся Господь і не розкається"},{"v":"5","t":["Господь, каже, буде з Тобою, Христе, як з людиною, щоб допомагати Тобі, як каже й у 15-му псалмі: Я бачив Господа перед Собою завжди, бо Він праворуч Мене, щоб Я не захитався. Сам, каже, Господь у день суду розтрощить нечестивих царів призначеними їм вічними муками; а якщо розтрощить царів, то чи не набагато більше й інших нечестивих?","Прим.: Слова Ісихія: чи бачиш, що слова «сядь праворуч Мене» означають не якесь місце, а єдність Сина з Отцем і цілковиту рівність? Бо якщо справді праворуч, то як кажеться також, що й Отець праворуч Нього? А розтрощить у день гніву царів, що зібралися на Господа й на Христа Його: Ірода, і Пилата, і Анну, і Каяфу, і їхніх спільників. Або, на думку Дидима, вказує на мисленних царів, які, розтрощені, перестануть бути ворогами, бо Господь знищить усяке їхнє начальство в день суду. Феодорита: «Господь праворуч Тебе» — ніби так сказав: Ти маєш поєднане з Тобою Божество невідлучним."],"h":"Господь праворуч Тебе розтрощив у день гніву Свого царів"},{"v":"6","t":["Господь, каже, засудить народ, або засудить серед народів гідних осуду, і наповнить падіннями, бо скине для користі й упокорить багатьох, тобто тих, хто стояв погано — в нечесті чи у злі. Він же розтрощить ще й голови багатьох, тобто, одним словом, багатьох. Бо що там сказав окремо про царів, те тепер тут каже загалом про багатьох; а це розуміється не тільки про майбутній суд, а в іншому значенні означає й нестерпну Божу силу: бо коли розгнівається Бог, тоді розтрощить царів і зробить усе інше.","Прим.: Слова Золотоустого: судитиме, тобто засудить і покарає бісів, через яких грішили й впадали в нечестя. А не сказав, каже Ісихій, «судитиме», тобто засудить народи, а «серед народів», тобто диявола. Він засудив його, показавши його безсилля серед народів, і наповнив падіннями демонів, бо разом з ним скинув і його військо; бо, ввійшовши в землю через Свою смерть і знищивши смерть, розтрощив голови мисленних зміїв."],"h":"Судитиме народи, наповнить трупами; розтрощить голови багатьох на землі"},{"v":"7","t":["За Золотоустим, цими словами Давид пророкує про простоту поживи й життя Ісуса Христа, тобто що Він, провадячи життя убоге й без надмірностей, питиме з зимового потоку й сухого рову, що тече на дорозі цього життя. Або треба розуміти так, що, ходячи дорогою цього життя, Він питиме з потоку. А у вищому розумінні під зимовим потоком можеш розуміти, за словами Дидима, бурю й безліч спокус, що наводяться; під дорогою — тимчасове й минуще це життя; а під питвом — смуток і безперервність спокус. Отже, Христос, каже, питиме, тобто зазнає в цьому житті потопу, або безлічі спокус. Бо, як Він Сам, каже, зазнав спокус, то може допомогти й тим, кого спокушають (Євр. 2:18). А втім, за цю простоту, смирення й спокуси Він підніметься й прославиться, коли зійде на висоту й сяде праворуч Бога. Бо цей невибагливий спосіб життя не тільки ніскільки не зашкодив Йому, а ще й підніс Його, за словами Золотоустого, на висоту невимовної слави.","Прим.: Додаток із Золотоустого: бо який був у Нього стіл, таке й питво: стіл — ячмінний хліб, а питво — вода з потоку. Бо цей любомудрий спосіб життя Він проходив, навчаючи приборкувати черево, топтати марнославство, знищувати пиху. Після вочоловічення, каже, Він користуватиметься найбільшою невибагливістю, щоб ті, хто на дорозі, знали, як угамовувати спрагу. Слова Феодорита: думаю, що це пророцтво має іншу, найглибшу думку й натякає на таїнство страждання. Бо чашею він зазвичай називає страждання, як ось тут: нехай мине Мене чаша ця. А потоком називає юдеїв, які завжди мали божественну благодать, але не завжди нею користувалися, подібно до того як і зимовий потік не має безперервної течії вод. Отже, на дорозі цього тимчасового життя п'є чашу страждання від юдеїв, які мають висохнути, мов потік. Подібно до цього каже й апостол Павло: упокорив Себе, бувши слухняним аж до смерті, і смерті хресної; тому й Бог звеличив Його. Очевидно ж, що й це сказав по-людськи. Бо як Бог Він не смиренням піднісся, а, перебуваючи на Своїй висоті, упокорив Себе; а як людина Він дістав ту висоту, якої не мав."],"h":"З потоку на дорозі питиме, тому підніме голову"}],"110":[{"v":"0","t":["Алилуя.","І цей псалом — подячний.","Прим.: Афанасій же каже, що цей подячний псалом виголошується від імені апостолів, які викладають, які діла спасенного домобудівництва звершив Ісус Христос. А Феодорит думає, що цей псалом виголошується як подячний спів Богові від імені царя Йосафата за даровану йому перемогу над моавітянами, аммонітянами й ідумеями. Золотоустий і Оріген кажуть, що цей і наступний за ним псалом містять стільки літер, скільки має єврейська абетка, а саме двадцять дві, тому й зветься абетковим. Те саме каже й Ісихій: прекрасний напис на цьому псалмі — «алилуя», що означає хвалу Богові; він знаменитий і тим, що складений за числом єврейських літер. Іоан Літин у своєму Псалтирі каже, що оскільки в цьому псалмі тільки десять віршів, то в кожному з восьми перших віршів поміщено по дві літери єврейської абетки, а в останніх двох — по три, і так у десяти віршах поміщено двадцять дві літери єврейської абетки."]},{"v":"1","t":["Я, каже, дякуватиму Тобі, Господи, не тільки словами й не тільки просто язиком і устами, а й усім серцем моїм, з поривчастою й найпалкішою душею та найуважнішою думкою, звільнившись від усякої життєвої турботи й піднісшись до Тебе; дякуватиму і за благодіяння, які Ти завжди мені чиниш, і за ті, які чиниш іншим людям. Бо ця моя подяка Тобі — жертва, завжди готова, і легке приношення, а до того ж і справа необхідна, якої Бог завжди вимагає від нас, як боргу.","Прим.: Слова Ісихія: сказав «усім серцем моїм», щоб ми, з одного боку сповідаючись, з іншого — не були схильні до гріха, у якому сповідаємося, і щоб, рухаючись однією душевною ногою до правди, другої не залишали грузнути в багні гріха. Усе серце ми маємо віддати Йому як Будівничому й Творцеві всього його, Який не може прийняти половинного дару. Золотоустого: і Мойсей, каже, кладе такий закон, кажучи: люби Господа Бога твого всім серцем твоїм і всією думкою твоєю. А сповіданням, мені здається, він називає подяку: заспіваю, каже, дякуватиму."],"h":"Прославлю Тебе, Господи, усім серцем моїм"},{"v":"2","t":["У раді, каже, і зібранні правомисних людей великі всі діла Господні, які Він творить, чинячи чудеса, як раніше, так і тепер, і після цього, і які при створенні світу привів у буття з нічого. Бо ці діла слід розуміти і як Божі чудеса, і як творіння: адже праведники, збираючись в одне місце й міркуючи про такі Божі діла, не знаходять, щоб якесь із них було незначне чи негідне свого Творця — Бога; а все видається їм великим і таким, що має велику й глибоку мету, хоча багатьом іншим часто не видається таким через їхнє невірне й перекручене судження.","Прим.: Золотоустого: вони самі собою великі, але не видаються великими, коли не мають праведного судді про них. Так і сонце само собою світле й блискуче й освітлює весь усесвіт, але для хворих очима воно не таке, хоча не можна винити в цьому сонця, а ваду, що полягає в їхній хворобі; тому й Сирах сказав: діла Господні всі добрі, і кожній потребі свого часу можуть допомогти; і не можна сказати: це гірше за те, бо все свого часу виявиться добрим (Сир. 39:33–34); а також: не можна сказати: що це? навіщо це? бо все створене для їхньої користі (Сир. 39:21).","«Пристосовані до всіх бажань Його»","Інший тлумач переклав: «виконані досконало». Вищесказані, каже, Божі діла досконалі й зроблені точно, тобто пристосовані до всіх Божих бажань і спонукають розважливих і тямущих виконувати їх; бо хто, бачачи такі діла Господні чи чуючи про них, не збудиться ними до виконання всіх бажань Причини цих діл — Бога? Розважлива людина пізнає з них, що справді Бог їх творить і що Творець їх — людинолюбний. А бажання Божі — це животворні Божі заповіді.","Прим.: Тому й Золотоустий міркує: такі, каже, досконалі Божі діла, що дають уважним найясніше пізнання про Нього й для тих, хто бачить, служать замість книг, навчаючи до того ж не тільки богопізнання, а й благочестя. Аполлінарій під Божими ділами розуміє не тільки творіння, а й чудеса, що були в різні часи й звершені різними способами; а під Божими бажаннями розуміє чесноти. Слова Феодорита: усе, що Він творить, — і діло творення, і домобудівництво спасіння, — величне, незвичайне й гідне прославлення від усіх людей. Бо сповіданням тут називає подяку. Ісихія: діло Боже, каже, — це наше спасіння, про яке Христос сказав: діло звершив, яке Ти доручив Мені виконати. Це діло має подвійну властивість: одну, що залежить від нашого вибору, а іншу — від Божого людинолюбства. Бо наша справа — просити, а Його — дати. Отже, сповідання — наше, бо через сповідання ми виявляємо в собі відступлення від лихого життя й бажання доброго; а велич — Боже діло, бо великому личить співчувати малим і підносити смиренних. Тож Боже діло складається з того й іншого, тобто з Його величі й нашого сповідання."],"h":"У раді праведних і в громаді. Великі діла Господні"},{"v":"3","t":["Діла, каже, Господні — це подяка, хвала й велич; і не окремо те чи інше діло Господнє, а загалом і разом усяке Його діло: бо всяке Його діло здатне збуджувати до величного прославлення й подяки Богові, що його сотворив, кожен словесний розум, який його бачить чи чує про нього. Особливо ж ділом Господнім вважається Його вочоловічення.","«І правда Його перебуває на віки віків»","Ці слова Давид написав на втіху скривдженим і для напучення й виправлення кривдників. Він каже, що Божий суд, як вічний, чекає і скривджених, і кривдників, щоб першим дати спокій, а других віддати на муку. Або каже, що правосуддя Боже вічне, тобто незмінне й непорушне.","Прим.: Слова Золотоустого: тож не бентежся, коли бачиш людей, яких обмовляють, які незаслужено терплять напади, зазнають лиха. Бо є судилище непідкупне, є вирок неупереджений, що віддає кожному за гідністю. А якщо ти вимагаєш його нині, то дивись, щоб не виголосити вироку спершу на себе. Феодорита: нічого неправедного немає в Його ділах, а все прикрашається правдою; бо, вічно маючи її при Собі, Він нею всім керує."],"h":"Слава й велич — діло Його"},{"v":"4","t":["Вислови «згадав» і «пригадав Собі» та подібні до них пророки багато разів, як ми сказали в інших місцях, уживають щодо Божої дії. Отже, Давид каже, що Господь творить чудеса й не перестає чинити чудеса всякого роду, щоб через ці чудеса привертати найгрубіших людей до пізнання Його. Такі чудеса Він сотворив під час потопу, змішання мов, спалення Содому, за Авраама, і за Ісаака та Якова. Такі звершив у Єгипті під час виходу євреїв з Єгипту, у пустелі, у землі обітованій, у Вавилоні й, після звільнення з Вавилону, за часів Маккавеїв. Такі творив і в Христове пришестя, і після Христового пришестя — за часів апостолів, мучеників та інших святих, і донині творить такі чудеса загалом і окремо — у домах, містах і, за висловом Золотоустого, у кожній частині світу.","Прим.: Слова Аполлінарія: Христос, пригадуючи Собі події, передречені в давнину пророками, те, що було передречене, виконував самим ділом. Бо вони передрікали Божим Духом, пророкуючи про ті чудеса, що мали бути сотворені Ним. Так Ісая каже: і будуть знамення й чудеса в домі Ізраїлевому (Іс. 8:18). За словами Феодорита, можливо, і цар Йосафат каже, що Бог пригадав Собі давні чудеса, що були за наших предків. Бо новою перемогою, що сталася в наш час, Він нагадував нам Свою перемогу над єгиптянами водою, піднесенням рук Мойсеєвих — розгром амаликитян і звершення інших чудес; і ті славні чудотворення, що в невіруючих вважаються вигадкою, Ти, каже, зробив безсумнівними.","«Милостивий і щедрий Господь»","Тут навчає, що Господь, Який творить вищесказані чудеса, милостивий і щедрий; бо Він творить їх тому, що, бувши милостивим і співчутливим до людей, бажає їм вічного спасіння."],"h":"Пам'ять учинив про чудеса Свої"},{"v":"5","t":["Тут можна запитати: навіщо Давид каже, що Господь дає поживу тим, хто боїться Його, коли Він дає поживу й тим, хто не боїться Його? Розв'язуючи цей подив, скажемо, що поживою Давид називає тут душевний, словесний, духовний і небесний хліб, який Господь дає переважно тим, хто боїться Його. Під поживою можна розуміти також і духовну вечерю — Тіло й Кров Господні. Або цар-пророк каже це тому, що Бог часто живить тих, хто боїться Його, і чуттєвою їжею в разі їхньої потреби й нестачі, як прогодував, за словами Дидима, Ілію, Даниїла, єврейський народ і багатьох інших.","Прим.: Тому ці слова доречно промовляє священик під час подяки після обіду.","«Пам'ятатиме повік завіт Свій»","Юдейські тлумачі пояснюють ці слова так, що Бог згадав Свій завіт, тобто звершив і зробив непорушним Свій завіт про розмноження Авраамових нащадків і про успадкування землі обітованої. А ми, християни, разом з Аполлінарієм приймаємо ці слова як пророцтво про Христа. Бог, каже, згадає в належний вік завіт, даний Авраамові та іншим патріархам, тобто що в насінні твоєму (тобто в Христі) благословляться всі народи (Бут. 22:18)."],"h":"Поживу дав тим, що бояться Його"},{"v":"6","t":["Давньому єврейському народові Бог показав силу Своїх діл, тобто могутність у ділах через чудеса, які Він щодня творив; а християнському народові показав силу в ділах щоденними чудесами, явленими після Його вочоловічення. Для чого ж Він це робив? Щоб юдеям дати землю обітовану, у якій раніше жили народи, а нам, християнам, дати і обітовану землю, і ту, що належала іншим народам, тобто ту, якою заволоділи християнські царі.","Прим.: Слова Ісихія: сподіваючись на цю силу, апостоли ходили з проповіддю до всіх народів і дістали в спадщину всю землю, що навернулася через їхні слова й труди. Афанасія: лик, каже, апостольський сповістив народові, покликаному до віри, силу Христових діл, — замість того щоб сказати, що Він ті самі діла завжди творить Своєю силою."],"h":"Силу діл Своїх показав народові Своєму, щоб дати їм спадщину народів"},{"v":"7","t":["Деякі руками Отця називали Сина й Святого Духа, як Тих, Що створили все. А Їхнє діло — діло Святого Духа — істина, бо й Господь сказав: Він, Утішитель, наставить вас на всяку істину (Ін. 16:13); а діло Сина — суд. Ці дві речі — істину й суд — Писання часто відносить до Духа й Сина. Або каже так, що діла Христові істинні (а не примарні) і праведні, тобто сповнені, за словами Дидима, правди, розрізнення й домобудівництва на користь; тому й Ісая сказав про Нього: до істини доведе суд. А Золотоустий, пояснюючи ці слова, каже, що Писання багато разів істиною називає людинолюбство, і за цим значенням ми маємо розуміти, що Божі діла сповнені людинолюбства й правди, бо Бог завжди й усюди поєднує одне з одним. І якби Він уживав одне людинолюбство, то ми всі, за словами Золотоустого, впали б у недбалість; а якби, навпаки, уживав одну правду, то ми всі загинули б, і ніхто не спасся б.","«Вірні всі заповіді Його»","Заповіді, каже, Господні достовірні. Оскільки сказав «всі заповіді», то, по-перше, розумій заповіді, дані творінню, які зберігають небо, сонце, місяць, зорі, день, ніч, пори року, земля, ріки, озера, джерела, дерева, трави й загалом усе бездушне, одушевлене й нерозумне; по-друге, заповіді, від початку вроджені людському єству, які бережуть і самі язичники, що не мають писаного закону; по-третє, заповіді, написані в Мойсеєвому законі; і, по-четверте, нарешті, заповіді євангельські. Усі такі заповіді вірні, тобто сталі й незмінні: бо хоча деякі заповіді старого Мойсеєвого закону й змінені в новому євангельському законі, але змінені на кращі й вищі. Отже, ніщо не може їх порушити. Амінь кажу вам: доки не мине небо й земля, ані одна йота не мине з закону (тобто з Десятослів'я), доки не збудеться все; а також: небо, каже, і земля минуть, а слова Мої не минуть (Мт. 5:18; 24:35).","Прим.: Золотоустого: що означає «вірні»? Надійні, сталі; бо якщо будуть порушені, то настануть кари; вони непохитні; якщо ж люди переступлять їх, то Бог заступиться за них. Не кажи мені, що це сказано для погрози чи перебільшено. Бо жоден законодавець не говорить тільки для погрози, а й для напучення. Василія: якщо ж усі Його заповіді вірні, то ясно, що відкинути щось із написаного або запровадити ненаписане — це відпадіння від вірності й ознака гордості."],"h":"Діла рук Його — істина й суд"},{"v":"8","t":["Заповіді, каже, Господні тверді, вічні й незмінні, і в них немає жодної неправди чи кривизни й викрутасів, за Золотоустим. Або й інакше: під істиною розумій ясність і чистоту, а під правотою — правильність постанов, бо всі заповіді Господні істинні й ясні й навчають, як іти прямою дорогою чесноти."],"h":"Утверджені на віки віків, учинені в істині й правоті"},{"v":"9","t":["Отець, каже, послав Сина, тобто Христа, на визволення й звільнення Своєму народові: благовістити, каже, убогим послав Мене, проповідувати полоненим визволення (Іс. 61:1); і ще: Він спасе людей Своїх від гріхів їхніх (Мт. 1:21); і Павло сказав: Який став для нас премудрістю від Бога, праведністю, освяченням і викупленням (1 Кор. 1:30). Отець, каже, заповів повік Свій новий і євангельський завіт, тобто Свій вічний завіт: дам, каже, завіт вічний (Іс. 55:3). Бо даний Богом Мойсеїв завіт був тимчасовий, тобто з видимого боку писаний, а прообразно й приховано містив у собі новий завіт. Бо з приходом нового давній припинився.","Прим.: Ісихія: говорить про те визволення, яке звершив Спаситель, про яке й Захарія, після зачаття Христового, пророкуючи про Його народження, каже: благословенний Господь Бог Ізраїлів, що відвідав і вчинив визволення людям Своїм. Дидима: це визволення не відрізняється від Того, Хто сказав: Син Людський прийшов не для того, щоб Йому служили, а щоб служити й віддати душу Свою як викуп за багатьох; бо дорогоцінною кров'ю ми викуплені від марного життя, переданого нам від батьків, за словами Первоверховного.","«Святе й страшне ім'я Його»","Ім'я, каже, Христове святе, бо творить незліченні чудеса, і страшне, бо виганяє демонів і зціляє недуги. А якщо воно святе, то вимагає, щоб святі уста його вимовляли й прославляли.","Прим.: Слова Золотоустого: святе ім'я Його й страшне, тобто сповнене великої вражаючої сили й подиву. А якщо ім'я Його страшне, то чи не набагато більше сама сутність? Як же ім'я Його страшне? Його тремтять біси; його бояться недуги; його силою апостоли навернули весь усесвіт; ним, ужитим замість зброї, Давид повалив того ворога; ним звершено незліченні діла; ним освячуємося при звершенні святих таїнств. Ісихія: святе, бо Він зветься Помазанцем; а це помазання Господа — повнота всякої святості, про яке каже й Іоан: а ви маєте помазання від Святого. Воно й страшне, бо Він зветься Суддею, бо, каже, Отець не судить нікого, а весь суд віддав Синові. Феодорита: для віруючих святе й найбажаніше й виливає безліч благ, а невіруючих і тих, хто живе беззаконно, віддає на муку й кару."],"h":"Визволення послав народові Своєму, заповів повік завіт Свій"},{"v":"10","t":["Страх, каже, Господній — джерело, корінь і основа мудрості: бо, за словами Григорія Богослова, де страх, там дотримання заповідей, а де дотримання, там і очищення, там і просвітлення, а де просвітлення, там і виконання бажання. Далі каже, що добре розуміння дається тим, хто вправляється в мудрості, трудиться й має її, — бо буває розуміння й лихе, тому й написано: мудрі на злодіяння (Єр. 4:22). Або можна розуміти й інакше: розуміння добре, тобто корисне, не для тих, хто просто його має, а для тих, хто втілює його в добрих ділах і словах.","Прим.: Слова того ж Григорія: що означає «початок»? Джерело, корінь і основа; бо благоговіння — ніби опора й дно для вдосконалення і, так би мовити, пелюшки в початкових основах; бо не споглядання починають і закінчують страхом, а, поклавши в основу страх, очищаючись ним і, так би мовити, стоншуючись, підносяться на висоту. Феодорита: мудрістю називають не красномовство, а знання божественних речей. Отже, страх властивий початківцям, а досконалим — здобуття любові.","Прим.: Інший каже, згідно з Феодоритом: отже, страх Божий, як те, що починає, — початок мудрості; а під мудрістю тут розуміє не ту, що в словах, а й ту, що в ділах; не красномовство, а пізнання божественного. Так і зовнішні визначали мудрість, називаючи її знанням божественних і людських речей. А це знання дає страх Божий, що винищує зло, насаджує чесноту й переселяє на небо. Що ж мудріше за таку душу? Недостатньо, за словами Феодорита, для досконалості одного знання: споглядання вимагає й дії, і треба, щоб той, хто сподобився божественного розуміння, показав знання в ділах і вдосконалився в істинній і першій премудрості, яка не блищить словом, а є розумінням, що виявляється в ділах. Бо розум добрий, каже, у всіх, хто чинить його, а не в тих, хто його проповідує, тобто в тих, хто ділами його виявляє, а не словами сповіщає. Бо він вимагає не тільки слухача, а й виконавця. Євсевія: розуміння тоді добре, коли звершується ділами. Тому не просто назвав розумінням добрим, а «у всіх, хто чинить його». Бо тим, хто вправляється в розумінні, яке, за словами Дидима, не відрізняється від чесноти, може бути від неї користь, з якої вони пізнають її благо.","«Хвала Його перебуває на віки віків»","Хвала, каже, і славослів'я Христові вічні й безкінечні в ангелів і людей. Тож і ми повинні хвалити й дякувати Йому завжди.","Прим.: Золотоустого: яка хвала, скажи мені? Подяка, прославлення ділами. Євсевія: мета блаженних — бути з Богом, стояти перед Ним і вправлятися в богослов'ї й хвалі Йому. Дидима: це властиво богословам — казати, що хвала Його, тобто Того, про Кого богословствують, перебуває безмежний час. Оскільки Той, Кого вони хвалять, безсмертний, то неминуче й хвала має бути безкінечна й тривати на всі віки."],"h":"Початок премудрості — страх Господній, розум же добрий у всіх, хто чинить його"}],"111":[{"v":"0","t":["Алилуя.","Думаю, що вступ і початок цього псалма тісно пов'язані з кінцем попереднього псалма; тому й цей псалом має той самий напис, що й той, як його частина. Наприкінці одного говориться: «початок премудрості — страх Господній», а на початку цього: «блаженний муж, що боїться Господа». Деякі, як-от Золотоустий і Оріген, кажуть, що цей псалом містить двадцять дві літери єврейської абетки; і початки віршів цього псалма в єврейському Псалтирі мають ті самі початкові літери єврейської абетки, що й попередній псалом, який, як ми зауважили раніше, містить число літер єврейської абетки; тому й цей псалом, за словами Орігена, зветься абетковим. А оскільки літер єврейської абетки двадцять дві, а віршів у цьому псалмі тільки десять, то в кожному з перших восьми віршів поміщено по дві літери абетки, а в двох останніх — по три, як каже Літин і як ми сказали в попередньому псалмі. Здається, що цей псалом написано за літерами єврейської абетки тому, що він особливо налаштовує до моральності.","Прим.: Слова Феодорита: цей псалом дає охочим настанову в благочесті. А інші кажуть, що цей псалом майже пояснює слова апостола Павла: благочестя на все корисне, бо має обітницю життя теперішнього й майбутнього (1 Тим. 4:8); а такі обітниці подано в ньому разом."]},{"v":"1","t":["У попередньому псалмі Давид сказав, що страх Господній робить мудрим того, у кому він перебуває: початок премудрості — страх Господній; а в цьому каже, що страх Господній робить блаженним того, хто боїться Його: блаженний муж, що боїться Господа. Утім, блаженний не той, хто просто боїться Бога, бо так бояться й біси, а той, хто боїться Бога й береже Його заповіді. Простий страх Божий — страх слабкий і мертвий, а той страх, що змушує берегти Божі заповіді, — діяльний і живий.","Прим.: За словами Великого Афанасія, мужність — чеснота не тілесна, а душевна, де немає різниці чоловічої й жіночої статі, а всі душі, створені за образом Божим, носять на собі той самий відбиток і мають ту саму природу. Тож ці слова стосуються не тіл, а вибору душі. Багато жінок, і то найслабших тілом, вірою душі виявилися мужнішими за самих чоловіків, як Сусанна — проти суддів і як Яіл — проти Сісери. І на початку псалмів Дух, кажучи про спільне блаженство всіх християн, приписує його мужеві, кажучи: блаженний муж; бо Він не вважав жінок чужими цій обітниці, щоб приписувати її самим чоловікам, але мужність — чеснота одна у своєму роді; тому й ужив спільне для людей ім'я, кажучи «блаженний муж», щоб і чоловіки, і жінки — усі вважали це блаженство спільним, бо це ім'я «муж» узяте від мужності. Так і тут не тільки чоловіка називає блаженним, а під іменем мужності охоплює й жінок. Євсевій каже, що Давид зазвичай називає тим, хто боїться Господа, кожного, хто приходить до Бога з язичників. Бо й у 134-му псалмі після Ізраїля, Аарона й Левія закликає до хвали тих, хто боїться Господа; тому й у цьому псалмі блаженним називається не хтось інший, а тільки народ з язичників, що прийшов до Бога, якого й іменує тим, хто боїться Господа. Тож не блаженний такий, якщо до нього не стосується й наступне — велике бажання перебувати в Його заповідях; бо й біси бояться Бога, маючи один тільки страх, що походить від пізнання.","«Заповіді Його дуже полюбить»","Хто боїться Бога, каже, радітиме й веселитиметься заповідями Божими, бо саме це означає: дуже полюбить. Давид і в іншому місці, показуючи свою насолоду від Господніх заповідей, каже: і я підносив руки мої до заповідей Твоїх, які полюбив (Пс. 118:48); і ще: які солодкі гортані моїй слова Твої — солодші за мед устам моїм (Пс. 118:103).","Прим.: Слова Золотоустого: коли бажання до заповідей може бути сильним? Коли ми в усьому зокрема боїмося й любимо Бога. Сказавши «заповіді Його дуже полюбить», не сказав: заповіді Його виконає, а вимагає чогось іншого, більшого. Чого ж? Виконувати їх з ревністю, бути їхніми палкими любителями, любити їх не за нагороди, що за них приготовані, а ради Того, Хто їх установив; не зі страху перед геєною, не через погрозу кари чи обітницю царства, а ради Законодавця виконувати заповіді з усією ревністю. Бо труднощі зазвичай залежать не від властивості справ, а від лінощів багатьох, так що тому, хто приймає божественні повеління охоче, і найсуворіші можуть видатися легкими й дуже здійсненними."],"h":"Блаженний муж, що боїться Господа"},{"v":"2","t":["Нащадки, каже, того, хто боїться Господа, будуть на землі сильні, бо Бог зміцнюватиме їх проти тих, хто кривдить і шкодить їм. А нащадки його, за словами Ісихія, — це учні й наслідувачі його чесноти, що зберігають подобу й близькість до його похвального життя; для них чесноти їхнього вчителя становлять ніби їхню спадщину. Далі, рід правих серцем буде хвалений, і знову ж не родом розбещених, а правомисними.","Прим.: Золотоустого: тобто буде сильне і до відходу з цього життя, і до одержання тамтешніх благ, бо чеснота має віддяку в самій собі ще до нагород за подвиги й твердіша за камінь і міцніша за алмаз. Або буде сильне на землі лагідних для досягнення заслужених віддяк. Феодорита: оскільки для тутешніх людей цей дар видавався бажаним, то й обіцяє дати його тим, хто береже заповіді; і справді вже дав його ради Авраама Ізраїлеві, і ради Давида його нащадкам, і ради Ізраїля його дітям, навіть порушникам закону. Дидима: насіння мужа, якого названо блаженним за те, що має страх Господній, яке він сіє в добру землю — у своє ревне й добре серце, сильне настільки, що може приносити стократний плід. А насіння лихих, що сіють у плоть і в свій земний навик, слабке; тому й пожнуть від плоті тління; а насіння тих, хто сіє в дух, сильне, тому й пожнуть життя вічне."],"h":"Сильне на землі буде насіння його; рід праведних благословиться"},{"v":"3","t":["Слава, каже, і багатство від Бога, що полягають у добрих ділах, є в домі тієї людини, яка, за Золотоустим, боїться Бога. Або слава буде дана йому тими людьми, що шанують його чесноту; і багатство також, що полягає в збагаченні тими благами, які він здобуде; бо він і їх дістане, коли захоче, за ту вірність і надію, які має до Бога. До того ж і правда його, тобто виправдувальна чеснота, перебуватиме нетлінною у вічному житті, супроводжуючи його туди після смерті.","Прим.: Слова Золотоустого: Писання зазвичай називає багатством те, що полягає в добрих ділах. Так воно радить багатіти добрими ділами; а також: чи світ, чи життя, чи теперішнє, чи майбутнє — усе ваше. Чи бачиш велике багатство? Це справжнє багатство; а інше багатство — тільки порожня назва багатства, що не має нічого дійсного. У цьому відношенні що може бути багатшим за апостолів, у яких усе текло, як з джерел, і яких не обходило багатство, що полягає в грошах? Оце — не потребувати багатства — і є справжнє багатство. Вони мали славу — славу від Бога, яка також була поєднана з обітницею й давалася на додаток. А інший тлумач замість «правда» і так далі вжив: «милостиня його перебуває повік». Бо така дія й сила милостині, за Золотоустим, — безсмертя, нетління й те, що вона не може знищитися. Усе людське забирає час, а плід милостині — правди людини, що тому й зветься правдою, — перебуває безперервно безсмертним, не меншаючи ні від яких лихих випадків, а супроводжує й у майбутній вік, або, краще, випереджає й готує оселі. Афанасія: і слава, каже, і багатство тих, хто боїться Бога, не слід зараховувати до швидкоминущого, бо в святих вони не такі. Феодорита: і ці обітниці дає їм як тим, хто ще не досконалий і не здатний чути про досконалі речі. Бо досконалих Владика Христос навчає протилежного, коли каже: не беріть з собою ні золота, ні міді в пояси ваші, ні торби на дорогу, ні двох одеж, ні взуття, ні палиці; і ще: хто не зречеться всього, що має, не може бути Моїм учнем. Так Він і Соломонові додав славу й багатство; так і синам Ізраїля дарував багатство єгиптян. Дидима: це ти можеш зрозуміти, коли почуєш Павла, що каже: ми вбогі, але багатьох збагачуємо; нічого не маємо, а всім володіємо. Хто ж може бути багатшим за спадкоємця Божого й співспадкоємця Христового?"],"h":"Слава й багатство в домі його, і правда його перебуває на віки віків"},{"v":"4","t":["Бог, каже, засвітив тим, хто перебуває в темряві спокус і скорбот, світло свободи й утіху. Або можна розуміти, що Христос — світло істини, яке засяяло для тих, хто перебуває в темряві омани; тому Він і казав: Я — світло світу (Ін. 8:12); а це світло засяяло для правих, тобто тих, хто може право мислити, бо вони бачать і знають таке світло. Бог, каже, милостивий і щедрий, бо Він благий, і праведний, як суддя. Тут звернися до пояснення, зробленого нами на слова 100-го псалма: милість і суд оспіваю Тобі, Господи.","Прим.: Слова Феодорита: Писання темрявою називає інколи незнання, а інколи збіг неприємних обставин; так само й світлом — інколи знання, а інколи звільнення від лих. Отже, він каже, що Бог і тим, хто не знає, відкриє істину, і тим, хто в спокусах і сумних обставинах, виявить Своє піклування. Ісихія: чому праведним? Бо ті, хто чинить лихі діла, ненавидять світло, яке їх викриває, і не хочуть звернути до нього очей.","Прим.: Золотоустого: бо якщо Він такий милостивий, що й тих, хто грішить, часто сподоблює прощення, то чи не набагато більше не залишить без вінців тих, хто чинить праві діла, після їхнього відходу? А якщо Він і не віддає тут, то однаково віддасть там. Якщо Він праведний, то віддає кожному за заслугою, хоча тут і не віддає; і це особливо ясно доводить необхідність воскресіння. Бо оскільки багато доброчесних явно зазнають незліченних страждань, а багато порочних насолоджуються великою свободою, то де ж кожен дістане за гідністю, якщо не буде воскресіння, суду й відплати?"],"h":"Засяяло в темряві світло праведним: милостивий, і щедрий, і праведний"},{"v":"5","t":["Добрий, веде далі, той, хто співчутливий і милостивий до нужденних; хто дає, тобто позичає тим, хто потребує позики. Так і в 36-му псалмі написано: увесь день милує й позичає праведний. Такий милостивий упорядкує свої слова добре, говорячи розважливо, а не просто що спаде на думку й необдумано. Або й так: він розважливо й добре влаштує свої справи. Так і Симмах переклав. Або добре впорядкує свої відповіді на суді, тобто приготує собі милостинею допомогу й захист на майбутньому суді, за прикладом згаданого в Євангелії вірного й розумного управителя.","Прим.: Великого Василія: добрий і той, хто з любові до Бога уділяє ближнім з даного йому від Бога дару і хто, мов розумний управитель, роздає свого часу визначену міру хліба таким, як він, рабам, пропонуючи слова тайноводства не просто й не нерозважливо, а слухаючись слів: не давайте святині псам. Золотоустого: дивись, скільки нагород призначив людинолюбному! І плід його перебуватиме завжди, і від спокус він звільниться, бо це означають слова «засяяло йому світло»; і він наслідуватиме Бога, бо й Бог щедрий; і дістане прощення своїх гріхів; і приготує собі захист на майбутньому суді. Саме це й означає «упорядкує слова свої на суді», тобто дістане захист, дістане виправдання в словах, не буде тоді засуджений, бо милостиня добре влаштує для нього відповідь. Інший тлумач: влаштовуючи свої справи з розсудом, тобто, як каже Золотоустий, насолоджуватиметься великим добробутом, не впаде в безглуздя, ставши чудовим управителем. Бо як не назвати безглуздими тих, хто, коли в теперішньому житті загрожує небезпека, розтринькує все своє, щоб уникнути небезпеки, а маючи бути відданими понад небезпеку ще й карі, не вдається до такого розпорядження? Тому милостивого називає розумним управителем, бо він за невелике здобуває багато: одежею — небо, хлібом — царство, а чашею холодної води — майбутні блага. Що може зрівнятися з таким домобудівництвом? Феодорита: хто наслідує свого Владику, той щедро допомагає своїм співслужителям, виявляючи співчуття, як той, що має одну з ними природу, і подаючи милостиню, як той, хто чекає віддяки від спільного Владики. І такий нічого не робить без розсуду, а, здорово міркуючи, добре впорядковує і слова, і діла свої. Ісихія: влучно називає добрим не просто того, хто дає, а того, хто дає зі співчуттям: бо перший дає в надії на прибуток, а другий уділяє за законом співчуття. Отже, він ясно зображує тут нищелюбця. Такий позичає Богові, коли виявляє милість убогим, за словами Соломона (Прип. 19:17).","«Бо повік не похитнеться»","Милостивий, каже, і той, хто боїться Бога, не похитнеться від спокус у цьому віці, бо міцно заснований на камені віри в Бога, надії та любові й має совість непорушну, мов якір. За Золотоустим, не сказав, що не зазнає підступів, бо багато скорбот у праведних (Пс. 33:20), а що не похитнеться. Це й дивовижно, що святі, і зазнаючи незліченних лих, не змінюються, а зберігають непохитним і непорушним до кінця свій здоровий розум. Це справді славна перемога; блискуча слава й вість про подвижників чесноти. Або можна розуміти так, що милостивий не похитнеться в майбутньому віці, бо, каже, приготувався я й не збентежився (Пс. 118:60), як той, хто не відчуває у своїй совісті нічого безглуздого.","Прим.: Тому той самий Золотоустий сказав: це особливо дивовижно, коли він непохитний не в час, вільний від спокус, а завжди незмінний і за безлічі підступів."],"h":"Добрий чоловік, що милує й позичає; упорядкує слова свої на суді"},{"v":"6-7","t":["Праведника, каже, і милостивого люди згадуватимуть за його чесноти не тільки за життя, а й після смерті. І такий милостивий і праведник не злякається страшної звістки чи чутки; за Золотоустим, і тут не сказав, що не почує страшної звістки, а що не злякається цієї звістки, бо переправив своє багатство в недоступне для злодіїв місце, тобто на небо, милостинею, куди й сам прагне піти після смерті; адже, за запевненням Господа, де скарб ваш, там буде й серце ваше (Мт. 6:21). Тому праведник і милостивий не злякається й тих, хто вбиває тільки тіло, а душі вбити не може.","Прим.: Слова Феодорита: славний, каже, буде такий і знаменитий у всіх і досягне вічнопам'ятної слави, так що згадуватимуть його за чесноту не тільки за життя, а й після смерті. Тут скажемо із Золотоустим: як він у житті зазнає якогось лиха, коли й після кончини стане для інших учителем доброзичливості? Щоб і самі невіруючі знали, що плід його безсмертний на небесах, Бог ще тут дає цьому свідчення. Бо й після поховання й віддання землі його тіла пам'ять про нього лине всюди: така сила чесноти — вона не минає з часом, не в'яне від безлічі днів. А це служить на спасіння багатьом: його не зв'язує чужа похвала, а ті, хто живе в пороці, зв'язуються похвалами йому, так що через похвалу його подвигам вони стають кращими й можуть колись звільнитися від порочності. Ісихій: оскільки пам'ять про тутешніх багачів, чи царів, чи інших, хто в цьому житті став знаменитим, тимчасова, то він показує, що пам'ять праведних не така. Пахимер у примітках на Діонісія Ареопагіта каже: отже, ми не тільки творимо пам'ять святих, а й приносимо їх Богові на пам'ять. А те, що в пророків кажеться, що вони згадуються перед Господом, слід розуміти не так, ніби Божа пам'ять відновлюється в уяві пам'яті, як буває з розумними істотами, пов'язаними з тілом, тобто з нами; а Божою пам'яттю влучно зветься Боже знання, за яким Бог знає, що ті, хто доброчесним життям досяг досконалості, стали в Ньому богоподібними й сподобилися незабутнього знання про них.","Прим.: Слова Афанасія: страх тих, кого карають, не має жодного стосунку до святих. Ісихія: чи говоритимеш про смерть, чи про родичів, чи про дітей, чи погрожуватимеш позбавленням майна, — милостивий, каже, не злякається нічого зі згаданого. Про це може засвідчити й Йов, який на все, що з ним сталося, сказав: голим я вийшов з утроби матері моєї, голим і відійду."],"h":"На вічну пам'ять буде праведник, лихої звістки не злякається"},{"v":"8","t":["Симмах переклав: непохитне серце його. Серце, каже, праведника й милостивого тверде й непорушне в надії на Бога: він сподівається, що з Божою допомогою переможе й досягне спасіння, не боячись жодного зла.","Прим.: Золотоустого: чи бачиш, як будує свій дім на камені? Бо чого боятися голому й легкому, що нікому не дає приводу? Чого лякатися тому, хто має Бога милостивим і благоволительним, — ні підступів, ні наклепів? Бо в нього немає нічого, від чого може бути шкода; він з цього життя переселився в небесну країну, недоступну для злого задуму. Бо ви ясно знаєте, що всі підступи бувають щодо грошей і за гроші.","«Доки не подивиться на ворогів своїх»","Вороги праведника й милостивого — це біси. Отже, серце цього милостивого, каже, тверде, доки він не побачить своїх ворогів-демонів у лихах, яких, за Золотоустим, вони мають зазнати; і не злякається, доки не впадуть і не будуть скинуті його вороги, а тим більше не злякається після їхнього падіння. Бо Давид, сказавши про те, що ще сумнівне й недостовірне, тобто що праведник не злякається, доки не впадуть його вороги, замовчав про наступне, як про певне й безсумнівне, тобто що тим більше не злякається праведник після падіння його ворогів; бо й це властиво Писанню — уживати вислів «доки» невизначено, як ми зауважували в інших місцях.","Прим.: Феодорита: милостивий не тільки не боїться ворогів, а ще й чекає їхнього падіння завдяки надії на Бога."],"h":"Готове серце його уповати на Господа. Утвердилося серце його, не злякається"},{"v":"9","t":["Милостивий, каже, і праведник розсипав своє майно між убогими; словом «розсипав», за Золотоустим, виразив щедре подавання милостині й багату віддяку, яку милостиня дає милостивому; бо назвав її насінням, що родить стократний плід, адже сіячі сіють насіння на ниві; тому й правда милостивого, тобто його віддяка й нагорода, має перебувати завжди й бути вічною. Давид повторює те саме, щоб утвердити свої слова. Або правдою окремо називає тут чесноту, яку дає милостиня і яка виправдовує милостивого.","Прим.: Золотоустого: дивись, які чудові й самі вислови в пророка; бо не сказав «дав» чи «розділив», а «розсипав», і цим показує водночас і щедрість того, хто дає, і називає цю річ насінням, бо ця дія належить сіячам. Вони сіють свої запаси й роздають видиме, щоб одержати майбутнє, і таке сіяння набагато краще за збирання: розсипається майно, а збирається праведність. Це роблять і хлібороби, але вони — на непевне, бо приймає від них насіння земля; а ти — у руки Божі, де ніщо не може пропасти. Бо хто, мов землю, обробляє небо, той може бути певний і щодо капіталу, і щодо прибутку на нього, якщо тільки такий можна назвати прибутком, а не тим, що набагато перевершує сам капітал, — бо капітал становлять гроші, а прибуток — Царство Небесне. Чи бачиш, якої властивості ця позика? Що може бути дивовижнішим за це? Зібране гине, а розсипане перебуває. Великого Василія: дуже дивне те, що маю сказати, але найправдивіше. Бо багатство, коли його втримують, гине, а розсипане тим способом, який заповідає Христос, не тільки зберігається неушкодженим, а й повертається стократно й з великим приростом. Це показує й апостол: хто сіє щедро, той щедро й пожне. Феодорита: хто прикрашається страхом Божим, той не просто подає милостиню тим, хто просить, а й робить це з великою щедрістю й наслідує тих, хто сіє насіння не скупо й сипле його в надії на снопи. Ісихій сприймає це у вищому значенні: під убогими тут можеш розуміти тих, хто голодує за Божим словом, тобто ті народи, серед яких апостоли, мов хлібороби, сіяли мисленне слово.","«Ріг його піднесеться в славі»","Честь, каже, праведника й милостивого піднесеться. А що означає ріг, ми ясно сказали в 25-му вірші 88-го псалма, пояснюючи слова: і ім'ям Моїм піднесеться ріг його.","Прим.: Слова Ісихія: ріг у праведних — це надія на Бога, з якою ми, виходячи, вражаємо ворогів. Він і тепер високий, але для багатьох невідомий. Отже, він підноситься в славі, тобто в майбутньому віці, коли відкриється, яку він має велич і славу. Дидима: рогом називає Бога, бо всі праведники, сподіваючись на Нього, кажуть: Тобою ворогів наших заколемо рогами; так і той, хто зветься блаженним, перемігши своїх ворогів Господом, має свій ріг, яким скинув тих, хто підносився. Феодорит: рогом називає силу за подобою тих тварин, що озброєні рогами й ними захищаються від тих, хто на них нападає. Отже, він каже, що хто має багатство чесноти, той буде сильний і знаменитий."],"h":"Розсипав, дав убогим; правда його перебуває на віки віків"},{"v":"10","t":["Лиха, каже, і немилосердна людина, або диявол, бачачи, що милостивий виявляє милість убогим, гніватиметься, вважаючи людинолюбство милостивого викриттям своєї нелюдяності. Бо така річ, за Золотоустим, — чеснота: вона тяжка й протилежна всякому пороку; тому немилосердна людина скреготатиме зубами на милосердного, тобто милостивого, виявляючи скреготом зубів досаду й смуток у своєму серці. Але він не посміє нічого сказати проти нього, бо чеснота милостивого закриває йому уста; тому немилосердний розтане весь від скорботи через подвиги й чесноти милостивого і, з'їданий заздрістю, стане вбивцею самого себе. Але бажання його загине; бо оскільки його бажання, за Золотоустим, стосується тлінних і земних речей, то разом з їхнім тлінням і загибеллю тліє й гине бажання немилосердного. Деякі відносять слова «засяяло в темряві світло праведним» до богобоязної людини, яку Давид на початку псалма назвав блаженною, а не до Бога, так що милостивий просвітить затьмарені душі неслухняних і небогобоязних; а так само й наступні вірші відносять до нього ж, тобто що милостивий виявляє милість і щедрість і судить праведно.","Прим.: Слова Афанасія: грішником називає диявола, який, прагнучи загибелі всіх, обурюватиметься через спасіння народів. Ісихій і Севир під грішником також розуміють диявола. Бо диявол скрегоче зубами: йому властиво скреготати, як неприборканому левові. Але й він розтане від вогню геєнського, на який він призначений, де й скрегіт зубів, як каже Господь. Євсевій грішниками називає юдеїв і невіруючих язичників: перші скрегочуть через успіх віруючих язичників, а другі, невіруючі, — тому, що від них перейшли до богоугодного життя віруючі.","Прим.: Золотоустого: така лиха вдача: хоч би вона досягла й самих скіпетрів, вона перед усіма нікчемна й боязка. Вона певним чином подібна до шуму й хвилювання моря. Бо що може бути нещаснішим за того, хто живе у злі, коли він, понад те, що поневолює себе майну, тане й від подвигів інших і славу інших вважає своєю карою? Що ж означає «бажання грішника загине»? Ніде не зупиниться. А якщо такий стан грішника в цьому житті, то подумай, яким він буде в майбутньому."],"h":"Грішник побачить і розгнівається, заскрегоче зубами своїми й розтане; бажання грішника загине"}],"112":[{"v":"0","t":["Алилуя.","І цей псалом, як і попередній, — подячний Богові; тому має з ним один напис.","Прим.: За словами Афанасія, тут міститься настанова новому народові приносити безперестанну пісню Визволителеві, а водночас указується на покликання всіх народів."]},{"v":"1","t":["Отроками тут, за Феодоритом, називає рабів, бо й у 134-му псалмі каже: хваліть ім'я Господнє, хваліть, раби, Господа; очевидно, тих самих, кого тут називає отроками, там назвав рабами. А дехто під отроками розуміє незлобивих і невинних, або учнів Христових і учнів апостольських. Хваліть, каже, Господа й прославляйте Його не тільки словами, а й ділами: так, каже, нехай світить світло ваше перед людьми, щоб вони бачили ваші добрі діла й прославляли Отця вашого Небесного (Мт. 5:16).","Прим.: Золотоустого: треба, по-перше, виправити життя, і тоді співати пісні Богові, бо не гарна похвала в устах грішника (Сир. 15:9); по-друге, хвалити можна не тільки словами, а й ділами. І саме такої хвали особливо вимагає Бог; так хвалять і херувими. Тому пророк, почувши той таємничий спів, називає себе нещасним: горе мені, бо я людина з нечистими устами й живу серед народу з нечистими устами. Тому й Давид починає з горніх сил, кажучи: хваліть Господа з небес, хваліть Його, всі ангели Його. Тож треба стати ангелами, і тоді хвалити. Отже, ми не повинні дивитися на цю хвалу просто; але раніше за уста життя має подавати за нас голос, і раніше за язик має гучно говорити наша відраза до земного. Так і мовчки можемо хвалити Господа; так і, вимовляючи слова, згідні з життям, ми звершимо спів. Євсевія: під отроками розуміє чотирнадцятилітніх юнаків, кажучи: як отрокам, що не вміють хвалити Господа, мов провідник і вчитель, подає ці слова, якими слід хвалити."],"h":"Хваліть, отроки, Господа, хваліть ім'я Господнє"},{"v":"2","t":["Нехай, каже, буде ім'я Господнє благословенне в нас, благочестивих, а не зневажене. Як? Коли ми славимо Його словами й добрими ділами, як сказано вище; бо ім'я Господнє, за Золотоустим, саме собою благословенне, стає благословенним і в нас, коли благословляємо й прославляємо його не тільки гарними словами, а й добрими ділами. Нечестиві, бачачи такі наші добрі діла й слова, прославляють ім'я Владики нашого Ісуса Христа.","Прим.: Феодорита: ви, каже, як раби й ті, що дістали буття від Бога, маєте хвалити Його ім'я, хоч і не знаєте Його природи; бо Він має благословення й прославлення безпочаткове й вічне, що й означають вислови «відтепер і повік»; але й ви повинні приносити вдячну пісню, як Творцеві. Золотоустого: що ти кажеш? Воно не благословенне, якщо не благословляєш? Чи бачиш, що говорить не про благословення, що належить Йому й невід'ємне від Його природи, а про те благословення, що залежить від людей і про яке каже Павло: прославляйте Бога в тілі вашому й у дусі вашому."],"h":"Нехай буде ім'я Господнє благословенне відтепер і повік"},{"v":"3","t":["Ім'я, каже, Господнє гідне хвали й славне не тільки в Палестині та в Єрусалимі, як раніше, а в усіх частинах всесвіту. За Золотоустим і Феодоритом, Давид цими словами пророкує про слово євангельської проповіді, що поширилося по всьому всесвіту."],"h":"Від сходу сонця до заходу хвалене ім'я Господнє"},{"v":"4","t":["Високий, каже, буде Господь — не так, ніби тоді ставав високим, а так, що тоді відкриється високим для християн з народів, бо християни матимуть високе вчення про Господа й звеличуватимуть Його богогідними славослів'ями. Слава Господня на небесах, бо на небесах Його прославляють святі ангели. Можна розуміти це й окремо про Христа й ангелів, які при народженні Господа хвалили Бога й казали: слава во вишніх Богу, і на землі мир, у людях благовоління (Лк. 2:14).","Прим.: За словами Феодорита: і тут ці слова означають, що всі народи пізнали, що Бог — Всевишній і Творець усіх, Якого хвалять небесні ангели. Слова Золотоустого: як же Він високий у народів, тобто над усіма народами? Бо ми звеличуємо Його, не додаючи Йому висоти, — ні, а додаючи до богослужіння, поклоніння й усього іншого, маючи не такі поняття, які мали юдеї, а набагато вищі й більші. Ісихія: хоча Його тут прославляють, але ця слава підноситься на небо, де є нерукотворний жертовник, де безперестанно прославляють Його ангельські воїнства, яких у славослів'ї вміємо наслідувати й ми."],"h":"Високий над усіма народами Господь, понад небесами слава Його"},{"v":"5-6","t":["Ці слова Давид каже на докір і посміх фальшивим еллінським і язичницьким богам: який, каже, інший бог подібний до нашого істинного Бога? Безперечно, жоден. Він живе на висотах, на небі, але дивиться й униз, на землю. Як же Бог живе на висотах і на небі, коли Він же, за словами Ісаї, зміряв небо п'яддю, а землю — жменею Своєю, і наповнює небо й землю, перебуваючи всюди й у кожній країні, і коли Він неописаний і невмістимий, — і як живе на небі й дивиться на землю? Відповідаємо з божественним Золотоустим, що Давид, спершу зійшовши до грубості юдейського розуму й сказавши, що Він живе на небі й звідти дивиться на землю, після цього трохи підносить думку юдеїв до богогіднішого розуміння, коли каже «на небі й на землі», ніби кажучи так: Бог водночас і на небі, і на землі, і вгорі, і внизу, тобто Бог усюдисущий. Щодо цього звернися до пояснення слів 2-го псалма: той, хто живе на небесах, посміється з них. А інші слова «на небі й на землі» поєднують зі словами «хто, як Господь Бог наш?», тобто хто такий, як Господь і Бог наш на небі й на землі? Безперечно, ніхто.","Прим.: Слова Великого Василія: престолом Божим зветься небо через те, що небесні сили мають у собі пізнання Бога, Який ніби непорушно сидить на престолі; а земля — підніжжям через те, що люди на ній ледве можуть умістити щось останнє про Бога. Золотоустого: хіба не велике й те, про що говориться? Але коли зрозумієш, про Кого говориться, то побачиш, що цього дуже мало. Бо як живе на небесах Усюдисущий, Той, Хто каже: Я Бог близький, а не Бог далекий (Єр. 23:23)? Афанасія: тут дається настанова новому народові, що хоча Господь наш і вознісся, але й нині вся земля повна Його слави й користується Його наглядом. Ісихія: висотами називає святих; вони високі, бо не займаються нічим земним. Про них ясно каже Ісая: так каже Всевишній, що живе на висотах вічно; Святий у святих ім'я Його; Всевишній, що спочиває на святих (Іс. 57:15). Феодорита: і блаженний Мойсей каже: хто подібний до Тебе між богами, Господи? Хто подібний до Тебе, славний у святих? (Вих. 15:11). З цього ми висновуємо, що Бога не можна ні з чим порівнювати, бо жодна істота не може бути уподібнена Божому єству ні силою, ні дією."],"h":"Хто, як Господь, Бог наш, що живе на висотах і на смиренних дивиться на небі й на землі?"},{"v":"7","t":["Землею й гноїщем Давид називає нікчемність і прославляє Божу силу, яка легко змінює речі на що Їй вгодно, як пояснює Феодорит, і вбогого й нічого не вартого робить багатим і значним, а також нікчемного й бідного робить славним і знаменитим."],"h":"Що підносить з землі вбогого і з гноїща підіймає нужденного"},{"v":"8","t":["Не тільки, каже, Бог робить убогого багатим і бідного славним, а ще й садить його з начальниками свого народу й підносить його до гідності й сану князів. Під убогим і бідним, за словами Афанасія та Євсевія, можна розуміти й народ з язичників, якого Христос підняв від безчесних пристрастей, підніс через Євангеліє й зрівняв з апостолами, які є начальниками в Христовій Церкві, згідно зі сказаним: поставиш їх князями по всій землі (Пс. 44:17); тому й верховний Петро писав до християн, що прийняли рівну з нами дорогоцінну віру (2 Пет. 1:1).","Прим.: Про це Ісая сказав: за це благословлятиме Тебе народ цей убогий (Іс. 25:3).","Прим.: Інший каже: не тільки апостоли, а й патріархи — князі юдейського народу, з якими оселяться й ті, хто увірував з народів. І це каже Господь: багато прийде від сходу й заходу й возляже з Авраамом, Ісааком і Яковом у Царстві Небесному."],"h":"Щоб посадити його з князями, з князями народу Свого"},{"v":"9","t":["Цими словами Давид хвалить Бога за Його силу, що Він не просто змінює речі цього світу, а й саму природу та закони природи: бо Бог від неплідної й бездітної жінки заселяє дім і робить її матір'ю, що радіє своїми дітьми, тобто з бездітної робить багатодітною, як зробив у Старому Завіті Анну, матір Самуїла, і багатьох інших, а так само й у новоблагодатному, євангельському; тому й Ісая сказав: Я і ту, що народжує, і неплідну сотворив (Іс. 66:9). А деякі під домом тут розуміють сім'ю, що складається з дітей.","Прим.: Слова Феодорита: власніше й правдивіше це можна відносити до Церкви. Бо з неплідної й бездітної, якою вона була раніше, Він зробив її матір'ю, що радіє незліченними дітьми, згідно з пророцтвом: веселися, неплідна, що не народжувала, заспівай і заголоси, що не мучилася пологами, бо в покинутої дітей більше, ніж у тієї, що має чоловіка (Іс. 54:1). Справді, за словами Дидима, Церква з язичників стала численнішою й багатшою на дітей Божих, ніж та, що має чоловіка, тобто юдейська синагога. Вона, за словами Афанасія, стала й домом духовним, бо в ній живе Господь; вона стала й матір'ю, що радіє багатьма дітьми, бо її діти спаслися вірою в Христа. Її діти відрізняються від синагоги, яка не зраділа дітьми, бо вони віддані на погибель. Слова Григорія Ніського: думаю, що цими словами виражається й дівство. Бо наслідок тілесного поєднання — народження смертних тіл, а наслідок єднання з Духом — замість дітей, життя й нетління тих, хто з Ним єднається. Бо різні чесноти, матерями яких стають боголюбні душі. На це влучно сказати апостольське слово, що спасеться зі своїми дітьми мати таких дітей, яка радіє, як оспівав псалмоспівець. Бо справді радіє Діва-Мати, що народжує Духом безсмертних дітей і названа пророком неплідною через цнотливість. І Дидим, пояснюючи це у вищому розумінні, каже: кожна бездітна через неплідність душа оселяється Богом у домі — у Церкві Бога живого — і стає матір'ю діл, повчань, думок і слів, щоб веселитися разом з тими, кого вона народила від Божого слова, що живе з нею. Ісихія: тісне для мене місце, дай мені місце, щоб жити. І скажеш у серці своєму: хто мені їх народив? Я ж бездітна й удова; хто ж мені їх виховав? Я залишилася сама; звідки ж вони в мене? (Іс. 49:20–21). І ще хтось каже в примітках на Феодорита: тут можна розуміти й чудову переміну: той, хто сидів у гноїщі пристрастей, мов убогий, і не мав жодного блага, і був неплідною й бездітною душею, зазнавши доброї зміни, поставлений вище земного, багатіє благами й народжує добре дитя чесноти."],"h":"Що оселяє неплідну в домі матір'ю, яка радіє дітьми"}],"113":[{"v":"0","t":["Алилуя.","І цей псалом — подячний Богові. У ньому розповідається про благодіяння, які Бог у давнину зробив юдеям, прославляється Божа сила й ганиться, за словами Феодорита, безсилля ідолів.","Прим.: За словами Євсевія, у цьому псалмі відкривається, що Бог один — і в Старому, і в Новому Завіті, а за словами Афанасія, зображується покликання народів."]},{"v":"1-2","t":["Ізраїлем і домом Якова називає єврейський рід, а Єгиптом і варварським народом — єгипетський народ. Акила переклав: з народу іноплемінного. Отже, Давид каже, що після виходу євреїв з Єгипту юдейська країна стала Божою святинею, тобто присвяченою Богові, а єврейський народ став Божим уділом, бо перебував під Божою владою, керівництвом і розпорядженням. І хоча всі люди за природою були під Божою владою, як Божі творіння, але тільки євреї становили Боже володіння через привласнення й вибір, як окремий Божий народ, за поясненням Золотоустого.","Прим.: Слова Ісихія: Юдея означає сповідання, а Ізраїль — розум, що бачить Бога. Отже, спершу треба сповідатися, щоб стати Божою святинею й улаштувати з себе дім і храм Божий, і щоб так, удосконалившись через споглядання істини, стати справжнім Ізраїлем і, побачивши Бога чистим серцем, дістати блаженство."],"h":"Коли виходив Ізраїль з Єгипту, дім Яковів — з народу варварського, стала Юдея святинею Його, Ізраїль — володінням Його"},{"v":"3","t":["Червоне море, каже, пізнало Бога і Його силу й відчуло Його волю, немовби воно було одушевлене й незбагненним для нас способом розумне; тому, розділившись надвоє, побігло геть з очей і відкрило під собою на дні сушу, давши місце, щоб ізраїльтяни, виведені Мойсеєм з Єгипту, пройшли сухими ногами. А висловом «побігло» позначив, за словами Золотоустого, страх моря й поспішність, з якою воно розділилося й стало стіною праворуч і ліворуч.","«Йордан повернувся назад»","Це чудо сталося за Ісуса Навина, коли ріка Йордан спинила свою течію, давши Божому ковчегові й усьому ізраїльському народові змогу пройти по сухій землі, не замочившись. Про ці два чуда згадує Давид і в 65-му псалмі, кажучи: що обертає море на суходіл, ріку перейдуть ногами.","Прим.: Пояснення Ісихія: у вищому значенні під морем слід розуміти порочну поведінку, як мінливу, а під Йорданом — благодать хрещення. Отже, море життя тікає від того, хто сповідається, як гірке й несумісне з тим, хто назавжди відступив від гіркоти гріхів. А Йордан не тікає, а повертається для тих, хто сповідається, назад, оскільки вони змінюються, приступивши до сліз покаяння; бо покаяння звершується силою хрещення, і не було б жодної користі від покаяння без попереднього хрещення. Тому й Іоан спершу проповідував покаяння, а потім з покаянням поєднував хрещення. Чому Йордан повертається назад? Бо той, хто згрішив, через покаяння йде назад, покинувши колишню дорогу (бо Йордан сприймається як образ покаяння)."],"h":"Море побачило й побігло"},{"v":"4","t":["Бажаючи зобразити надзвичайну радість юдеїв після переходу посуху через Червоне море й ріку Йордан, Давид для цього прикладає почуття радості й гри до бездушних і безчутних речей; він каже, що й самі гори й пагорби, тобто і Синай, і Хорив, і юдейські гори, танцювали, тобто раділи, мов барани й ягнята. Бо барани й ягнята зовнішньою грою й стрибанням на квітучих луках виражають свою радість. Про радість бездушних ми говорили й у 95-му псалмі, пояснюючи слова «перед лицем Господнім, бо Він іде», де написано й таке: нехай веселяться небеса й радіє земля; звеселиться поле й усе, що на ньому."],"h":"Гори заграли, мов барани, і пагорби — мов ягнята в отарі"},{"v":"5-6","t":["За словами Феодорита, пророк Давид розмовляє з бездушними стихіями й речами, уживаючи ораторське уособлення, і, питаючи Червоне море та Йордан, а також гори й пагорби, каже до них: навіщо ви це робите? Навіщо ти, море, побігло з очей? І ти, Йордане, навіщо повернув свої струмені назад? І ви, гори, навіщо почали скакати, мов барани, а також ви, пагорби, навіщо граєте, мов малі ягнята? А такими питаннями показує, що з ними сталося щось незвичайне й надприродне.","Прим.: Золотоустого: зауваж особливість Писання: коли воно хоче сповістити про щось дуже корисне чи дуже шкідливе, то представляє й самі бездушні речі такими, що відчувають, — не тому, що вони відчувають, а тому, що бажає цим виразити, наскільки велике те, що сталося. Так зазвичай і ми кажемо, що саме місто було в смутку, саме лице землі потемніло, самі камені подавали голос. Григорія Богослова: Писання часто уособлює багато бездушних речей, як-от: море казало те й те; безодня сказала: немає в мене (Йов 28:14); і небеса розповідають про славу Божу; і гори й пагорби питають про причину їхньої гри. Ісихій, пояснюючи це у вищому розумінні, каже: радіють усі пророки, бачачи навернення тих, хто сповідається; з них одні, як ті, що дістали більше благодаті, звуться горами й баранами, а інші, як ті, що прийняли меншу її частку, але споріднену з великими, — пагорбами й ягнятами."],"h":"Що тобі, море, що ти побігло, і тобі, Йордане, що ти повернувся назад? Гори, що ви заграли, мов барани, і пагорби — мов ягнята в отарі?"},{"v":"7","t":["Тут сам Давид відповідає на питання, яке поставив раніше бездушним, бо, як пояснює Феодорит, вони не могли відповісти за себе через брак розуму. Він каже: від явлення Господнього здригнулася, тобто заграла, земля в образі гір і пагорбів. А Його явлення можеш уявляти те, що було на горах Синаї та Хориві, і прихід Бога на юдейські гори, як сказав і в раніше згаданому 95-му псалмі: тоді зрадіють усі дерева лісові перед лицем Господнім, бо Він іде. А Богом Якова назвав Його відповідно до таких слів: Я — Бог Авраама, і Бог Ісаака, і Бог Якова (Вих. 3:6).","Прим.: Євсевія: цими словами виражається покликання народів. У давнину лише якесь відчуття було в моря, ріки, гір і пагорбів; а нині, каже, нехай струсонеться й похитнеться вся земна стихія, або краще, за висловом Акили, нехай буде в муках породіллі, щоб виконалося сказане Ісаєю: хто чув таке? І хто бачив подібне? Чи мучилася земля пологами за один день? Чи народився народ одразу? Бо мучився пологами Сіон і народив дітей своїх (Іс. 66:8)."],"h":"Від лиця Господнього здригнулася земля, від лиця Бога Якового"},{"v":"8","t":["Заграла, каже, земля перед лицем Господа, Який тверду за природою й суху скелю обернув на озеро, повне води, а граніт, такий твердий і пружний, що ледве маленьку частку можна було відсікти від його краю залізним знаряддям, став джерелом вод. А кажучи це розлого, Давид хоче тим більше показати величину чуда.","Прим.: І Феодорит цей «камінь, що не відсікається», пояснив так: і в тому, що не мало жодної вологи й через твердість навіть не піддавалося сіканню, Він відколов край, щоб вилилися води, звелівши вийти з нього рясним джерелам. Григорій Ніський пояснює це у вищому значенні так: скам'яніла від холоду ідолопоклонства людська природа, замерзнувши, була нерухома до чогось кращого; але, зігріта Духом і запалена промінням Слова, знову стала водою, що тече в життя вічне; і та, що мала вигляд каменю через урвища ідолопоклонства, відновлена й стала дитям патріарха через наслідування його чесноти. А Ісихій каменем, що не відсікається, називає, згідно з Павлом, Христа, Який обернув Себе на озера й джерела вод; бо, коли спис відкрив Його ребро, Він вивів озера хрещення й джерела таїнства: адже кров потекла з Нього на образ таїнства (тобто Євхаристії), а вода — на знамено хрещення."],"h":"Що обернув скелю на озера водні, і кремінь — на джерела вод"},{"v":"9","t":["Виклавши вище давні благодіяння, які Бог зробив євреям, тепер Давид молиться тут Богові за сучасних йому юдеїв і каже: не для нас, Господи, чини милість, не за наші чесноти; бо ми не маємо чеснот і зовсім недостойні цього, як недостойні були й наші давні предки, що користувалися вищезгаданими благодіяннями; але дай, тобто зроби, щоб прославилося ім'я Твоє. Чим? Твоєю милістю, і то милістю та істиною, тобто виявивши нам милість і по-справжньому помилувавши нас. Бо Давид милістю й істиною часто називає милість істинну, тобто справжню, уживаючи «істину» замість прикметника; і власне Божу порівняно з людською, яка щодо Божої — несправжня й є милістю тільки через участь у першій.","Прим.: Євсевія: можливо, Давид тут приймає на себе особу ізраїльтян, що просять прилучити їх до покликаних народів і кажуть: ми недостойні тієї благодаті, якої сподобилися всі народи; але, Владико, зроби це не для нас, а для імені Твого, яким ми наречені від початку, і не ради наших праведностей, а даруй це з Твоєї милості й істини. Золотоустого: не для того, щоб зробити нас славнішими й знаменитими, а щоб зробити всюди відомою Твою силу. А ім'я Його прославляється і тоді, коли Він заступається за нас і допомагає нам, і тоді, коли ми живемо й сяємо доброчесним життям. Ісихій під милістю й істиною розуміє Христа, а славою називає ту, яку Отець дав Самому Собі через втілення Єдинородного, через Якого Він прославився й став відомим. Так Господь казав і в Євангелії: Отче, прослав ім'я Твоє. Як же Він прославив? Через наше спасіння."],"h":"Не нам, Господи, не нам, а імені Твоєму дай славу, з милості Твоєї й істини Твоєї"},{"v":"10","t":["Помилуй, каже, нас, Господи, і не дозволь нашим ворогам і народам заволодіти нами, щоб не сталося так, що народи ганьбитимуть Тебе й, сміючись, казатимуть: де Бог євреїв, що не приходить їм на допомогу? — тобто щоб не казали, що Ти безсилий і тому не допоміг нам."],"h":"Щоб не сказали коли народи: де ж їхній Бог?"},{"v":"11","t":["Народи, каже, за словами Дидима, можливо, скажуть вищезгадані слова; але Ти, Боже наш, сотворив ті створіння, які були Тобі вгодні, і на небі, і на землі. А часто довготерпиш і зносиш пороки людей за Своїм промислом, даючи грішникам час на покаяння.","Прим.: Золотоустого: що означає «сотворив на небі, що схотів»? Або горні сили, або повеління, які легко виконуються. Дидима: «на небі» означає не щодо місця, а щодо переваги величі. Бо якби Він був тільки в горішньому місці, то в іншому не міг би бути. Але Він усюди — і на небесах, і на землі. Будучи відмінним від усього, Він не замикається ні в чому, а перебуває й поза всім, і в усьому щодо творіння й промислу. А якщо все з волі Бога дістало буття, то дуже нечестиве міркування тих, хто буття Сина Божого виводить з полум'яної волі Бога Отця, ставлячи Його в число небесних істот, приведених у буття волею Отця. Нехай почують ці нечестивці, що тільки творіння поставив він у залежність від бажання Бога. Ісихія: Він, каже, на небі й на землі не тільки як Той, Хто все наповнює, а й як Той, Хто народився на землі плоттю, і не просто, а підкоривши бісів і звільнивши творіння від зітхання."],"h":"А Бог наш на небі й на землі; усе, що схотів, сотворив"},{"v":"12-15","t":["Цими словами Давид ганить ідолів і фальшивих язичницьких богів і, за словами Золотоустого, широко розповідає про всі їхні члени, щоб збільшити ганьбу їм; і спершу він ганить обриси їхніх зовнішніх чуттів — уста, очі, вуха, ніс, руки й ноги, а потім ганить самі ці чуття, кажучи, що вони без жодної дії й становлять одну бездушну речовину. Тут хтось може запитати: чому не сказав про уста ідолів, що вони не їдять, як сказав про очі, що вони не бачать, і про вуха, що не чують, і так само про інші їхні чуття? На це відповідаємо: тому, як мені здається, що ми часто й про Бога кажемо, що Він бачить, чує, відчуває запах, ходить і говорить, але не кажемо, що Він їсть (можливо, бо це надто грубо). Тому Давид замість того, щоб сказати, що уста ідолів не їдять, сказав: не говорять; тому й раніше, і потім говорить про мову й голос, бо мова й голос — найясніший доказ розумного життя, тобто хто говорить, той ясно виявляє в собі розумне життя. А оскільки ідоли не мають мови, то вони бездушні, нерозумні й мертві.","Прим.: Феодорита: Ти, каже, твориш, що Тобі вгодно, а шановані в народів ідоли не творять, а їх творять, і ціну свою вони мають від речовини — від золота чи срібла, з якого їх роблять, а від митців дістають гарний вигляд. Бо срібники, золотарі й маляри роблять їх. І ще: оскільки біси, діючи через ідолів і вимовляючи брехливі віщування, робили це не через бездушних ідолів, а через мислячих людей, або сповіщали якимись знаками, то влучно сказав, що не можуть подати голосу гортанню своєю. Бо всі ідоли цілком бездушні."],"h":"Ідоли народів — срібло й золото, діло рук людських: уста мають — і не говорять, очі мають — і не бачать, вуха мають — і не чують, ніздрі мають — і не чують запаху, руки мають — і не торкаються, ноги мають — і не ходять, не подають голосу гортанню своєю"},{"v":"16","t":["Ті, каже, хто робить ідолів, а потім кланяється їм, як богам, і сподівається дістати від них спасіння, і сліпі, і глухі, і безчутні, як сліпі, глухі й безчутні ідоли, яких вони виготовляють і шанують. Але ідоли, каже, язичників безчутні; тож і ті, хто кланяється їм, безумні й не дістають від них жодної допомоги. А ми, як ті, що поклоняються істинному Богові, не такі.","Прим.: Того ж Феодорита: бо ті, кого вшановано розумом і хто впав у таку нерозважливість, справедливо мають бути покарані безчутністю того, чому вони кланяються. Євсевія: були подібні до ідолів; бо якби бачили, то не вважали б ідолів богами, і, маючи слух, не уявляли б бездушних такими, що говорять і дають віщування. Якби ходили правою дорогою, давно б відступили від омани щодо ідолів. Золотоустого: хоча уподібнення Богові — чеснота, але тут воно сприймається як прокляття. Тож подумай, які ті, уподібнення до кого вжито в мові як найкрайніше прокляття. Дидима: не людей проклинає, а хоче цим показати, що це спіткає ідолопоклонників. Бо їм це не може видатися прокляттям — що вони стануть, на їхню думку, богами, — а ще чимось і бажаним, і дивовижним."],"h":"Нехай подібні до них будуть ті, що роблять їх, і всі, що надіються на них"},{"v":"17-19","t":["Ми, каже, юдеї, не марно надіялися на Господа, бо Господь допомагає нам і захищає нас. Тут поділяє юдеїв на простий ізраїльський народ, на священичий рід і на прибульців, тобто тих, хто приходить з язичників до законного богошанування. Домом Ізраїлевим називає простих ізраїльтян, яких ставить на першому місці через їхню численність; домом Аароновим іменує священичий рід, бо Аарон раніше за всіх старозавітних священиків священнодіяв і був коренем пізніших ієреїв; нарешті тими, що бояться Господа, називає прибульців з язичників, бо вони прийшли до юдейської віри й тому, за словами Афанасія, боялися Господа.","Прим.: Золотоустого: у цій мові розрізняє Ізраїля від священичого роду й тих, хто приходить до Нього. Бо не те саме священик і простолюдин, а перший має перевагу перед другим. Дидима: кожен з-поміж проникливих, як той, хто має розум, що бачить Бога, — дім Ізраїля, бо становить Церкву Бога живого. Феодорита: тут показує, що й той, хто не має сану священства й не належить до роду ізраїльтян, але завдяки своїй старанності в чесноті прикрашається страхом Божим, скористається Божим піклуванням нарівні з усіма."],"h":"Дім Ізраїлів надіявся на Господа: помічник і захисник їм Він. Дім Ааронів надіявся на Господа: помічник і захисник їм Він. Ті, що бояться Господа, надіялися на Господа: помічник і захисник їм Він"},{"v":"20-21","t":["Господь, каже, згадав нас, Своїх рабів, і тому благословив нас. Що ж означає слово «благословив»? За Золотоустим: сповнив нас незліченними благами; бо від самого початку, починаючи з наших предків до нашого часу, не виключаючи й нас, їхніх нащадків, Бог не переставав благодіяти нашому юдейському родові. І тут так само поділяє народ на три частини, як поділив раніше; а про малих і великих говорить загалом щодо всіх трьох частин; малими й великими називає не тільки за тілесним зростом і літами життя, а й за силою та безсиллям, а так само й за багатством і бідністю, за знаменитістю й незнаменитістю, за свободою й рабством; тобто Він благословив і високих, і низьких, і старих, і молодих, сильних і безсильних, багатих і вбогих, славних і неславних, панів і слуг.","Прим.: Золотоустий додає й таке: що означає «благословив»? Сповнив, каже, незліченними благами. І людина благословляє Бога, наприклад, кажучи: благослови, душе моя, Господа. Але той, хто благословляє Бога, сам дістає від цього користь, ставши через це світлішим, а Йому нічого не дає. А коли Бог благословляє нас, то Сам нічого не здобуває, бо Божество не має потреб. Тож і в тому, і в іншому випадку користь нам. Слова Феодорита: той самий поділ зробив і тут, де показує плід надії. Бо благословення поєднує з надією й каже, що Він дає його не тільки домові Ізраїлевому й домові Аароновому, а й тим, хто боїться Його. Ісихія: коли Бог забув людей? Ніколи; але цими словами виражає таке: перебуваючи під прокляттям, ми не інакше могли звільнитися від нього, як через те, що Христос узяв наше прокляття на Себе, коли був повішений на дереві. Тому влучно каже, що Господь спершу згадав, а потім благословив нас. Інший каже: Бог пам'ятає всіх, хто пам'ятає Його."],"h":"Господь, згадавши нас, благословив нас: благословив дім Ізраїлів, благословив дім Ааронів, благословив тих, що бояться Господа, малих з великими"},{"v":"22","t":["Господь, каже, нехай розмножить і нас, і синів наших, і нехай додасть нам ще більше благ. У деяких списках стоїть друга особа: «вам і синам вашим»; а з цього видно, що Давид молиться про додавання й розмноження християнського роду, бо він розмножився більше за юдеїв, і йому додано істинні й небесні блага."],"h":"Нехай додасть Господь вам, вам і синам вашим"},{"v":"23","t":["І ці слова слід розуміти про християн, яких благословив Владика Христос під час Свого вознесіння на небо, як розповідає Лука: і, піднявши руки Свої, благословив їх (Лк. 24:50); бо, благословивши апостолів, через апостолів благословив усіх християн.","Прим.: Золотоустого: чи бачиш, яка сила благословення? Бо Його слова — це саме діло. Так небо створене Його Словом: бо Словом Господнім утвердилися небеса. Цим таким могутнім Словом Він і тебе благословляє."],"h":"Благословенні ви Господом, що сотворив небо й землю"},{"v":"24","t":["Перше, каже, небо, яке Бог сотворив на початку творення чуттєвого світу і яке є, за словами Феодорита, покровом для цього видимого неба, що зветься твердю, — воно служить оселею для Господа; тут згадай пояснення слів «що живе на висотах» у попередньому, 112-му псалмі. А землю дав людям на оселю й користь, для них же її й сотворив.","Прим.: Феодорита: Господь, що панує над усім, живе на небі не тому, що Його єство обмежене, а тому, що Він радіє ликами ангелів, які там живуть. Золотоустого: це не означає, що Він, узявши горішні місця, нам поступився дольніми, — зовсім ні. Але це вислів поблажливості. Бо якби було так, то як мали б місце інші Божі слова: чи не Я наповнюю небо й землю, каже Господь? Бо ці слова суперечать тим. Отже, він уживає поблажливе слово, не замикаючи Бога на небі, а показуючи, що Він спочиває в тих, хто там живе. Інший каже (можливо, Дидим): хто може споглядати це в найглибшому розумінні, той скаже, що є якесь небо, яке в Писанні особливо зветься небом і належить Богові, на якому один Бог. Так диявол до свого переступу, перебуваючи на небі, казав, ніби він десь унизу: на небо зійду, вище за зорі небесні поставлю престол мій. На це небо ніхто не сходив, тільки Той, Хто зійшов з небес, Хто й прийшов, бувши посланий звідти, і каже: Я зійшов з небес. І також Дух Святий посланий з цього неба, як каже Петро: Духом Святим, посланим з неба. Бо де Отець, там і Син, і Святий Дух. І це небо не місцеве, а, так би мовити, особлива перевага й стан Божий. Майже те саме каже й блаженний Августин у 36-му розділі своїх «Усамітнених бесід»: бо, недосяжний для споглядання, невидимий і вищий за всякий розум і поняття, як зовсім неприступний, незмінний і незбагненний, Він постає перед вірою; Його світла ніхто з людей чи ангелів не бачив і не може бачити. Це Твоє, Господи, небо — небо, що приховує найпотаємніше, незбагненне, невимовне й таке, що перевершує всяку сутність, світло; про нього кажеться: небо небес, для якого це небо — земля, бо це небо понад усякий подив піднесене вище за всяке небо, навіть вогняне. Тому й сказано: небо небес — Господеві, що нікому іншому воно не відоме, тільки Господеві, і на нього ніхто не сходив, тільки Той, Хто зійшов з небес. Бо ніхто не знає Отця, крім Сина й Їхнього Духа, і ніхто не знає Сина, крім Отця й Їхнього Духа, і так само ніхто не знає Духа, крім Отця й Сина, Яким належить Дух Святий. Ісихія: чи бачиш, як Творець поділився з нами Своїм творінням? Як Сам невидимий, Він має в Себе невидиме небо — небо небес, а нам поступився видимим творінням."],"h":"Небо небес — Господеві, а землю дав синам людським"},{"v":"25-26","t":["Ці слова подібні до сказаного в іншому місці: чи прославлятиме Тебе порох? Чи сповістить він істину Твою? (Пс. 29:10), і до такого: чи розповість хто в гробі про милість Твою? (Пс. 87:12). А на думку тих, хто заглиблюється більше, Давид мертвими називає тих, хто став мертвим для діяння чесноти й раніше, ніж тіло зотліло від природної смерті, зотлів від добровільної смерті, що полягає в гріху; а живими, навпаки, називає тих, хто живе доброчесно й переходить від цього низького життя до життя вищого й божественного. Бо мертві для чесноти не можуть славословити Бога в цьому житті, адже, за словами Сираха, не гарна похвала в устах грішника (Сир. 15:9), та й у майбутньому житті не хвалитимуть Бога, бо завжди терпітимуть муку; а ті, хто живе доброчесно, прославлятимуть Бога і тут, і там, відтепер і повік. До того ж мертві для чесноти йдуть до аду, а живі для чесноти сходять на небо. А кажучи «ми, живі», Давид цим указує на тих, хто був подібний до нього чеснотою, тобто був доброчесний, як він.","Прим.: Тому Золотоустий сказав: мертвими називає не тих, хто скінчив життя, а тих, хто вмирає в нечестивих ділах або зогнив у гріхах; бо й Авраам помер, і Ісаак, і Яків, але й після цього вони жили, тому й згадувалися разом з живими. І взагалі живими називає праведних. Бо як Бог — життя й правда, так і праведники через спілкування з Ним звуться живими. А Феодорит і Афанасій мертвими тут називають тих, хто обожнює мертвих ідолів і не має в собі життя, тобто відання єдиного Бога, а живими — тих, хто поклоняється живому Богові, яким Він доручив божественну пісню. Понад те, навчає, що ті, хто служить Богові, мають з усією ревністю прославляти Його, доки ще живі, бо смерть перешкоджає це робити: співатиму, каже, Господеві за життя мого, співатиму й гратиму на псалтирі, доки я є."],"h":"Не мертві хвалитимуть Тебе, Господи, і не всі, що сходять до аду, але ми, живі, благословлятимемо Господа відтепер і повік"}],"114":[{"v":"0","t":["Алилуя.","І цей псалом — подячний Богові, як і попередній.","Прим.: Інший каже, що цей псалом містить подяку за повернення з Вавилону. Або, за словами Феодорита, пророкує про ті лиха, яких завдав Єрусалимові Антіох Єпіфан."]},{"v":"1-2","t":["Я, каже, полюбив Бога (бо цього слова бракує, і його слід додати) і звеселився, бо Він почув моє моління й прихилив Своє вухо, зійшовши до моєї немочі, як ми сказали й у 16-му псалмі, пояснюючи слова: прихили до мене вухо Твоє й почуй слова мої; тому й надалі я призиватиму ім'я Господнє в усі дні мого життя.","Прим.: Слова Ісихія: хто, за вченням попереднього псалма, прилучився до тих, що бояться Господа, той тепер, перейшовши від страху до любові до Бога, може сказати: я полюбив Його; бо не кожен може сказати це, а тільки той, хто вдосконалився й піднісся над рабським страхом і досяг духа всиновлення. Великого Василія: до дієслова «полюбив» не додано, кого. Але ми маємо мати на увазі Бога всіх; бо власне гідний любові Бог, адже бажаним благом визначають (тобто Арістотель) те, чого все прагне; а таке благо, і перше, і останнє, — Бог. Отже, Його я полюбив — Бога, Який є межею бажань, і з радістю прийняв за Нього страждання. Які ж страждання, викладає трохи згодом: муки смертні, біди адські, і скорбота, і біль; усе це видавалося йому приємним з любові до Бога й з надії на ті блага, що приготовані тим, хто страждає за благочестя. Бо не проти волі, не силоміць і не з примусу я, каже, вступив у ці подвиги, а з певною любов'ю й прихильністю поніс тягарі, тож можу казати: за Тебе нас умертвляють увесь день; і: хто відлучить нас від любові Христової? Тож я полюбив усе це, знаючи, що терплю лиха за благочестя перед очима Глядача й Подвигоположника — Владики всіх. Я полюбив, і в нагороду за цю любов дістав те, що мене почуто. Золотоустого: багато з людей, що люблять життя, не хочуть чути того, що їм корисне, а тим часом просять дарувати їм корисне; а коли просимо буде дане, сумують і обурюються. Бо корисне — те, що Бог визнає таким, хоч би ти вказав на бідність, чи на голод, чи на хворобу, чи щось інше таке. Отже, я, каже, за найтяжчі болі й небезпеки полюбив Бога, бо Він почув мене й дав мені корисне. І ще каже: «прихилив вухо Своє до мене» сказав, щоб показати свою неміч: що й до того, хто лежить долі, Він зійшов зі Свого людинолюбства. Інший каже: Божий слух не потребує чуття, бо може знати, чого ми просимо, з одного руху серця. Хіба не чуєш, що Мойсей, хоч нічого не казав, а тільки стогонами без слів молився Господеві, був почутий Господом, Який сказав йому: чого ти взиваєш до Мене? Саме стояння з праведними ділами — гучний голос перед Богом."],"h":"Полюбив я, бо почує Господь голос моління мого, бо прихилив до мене вухо Своє, і в дні мої призиватиму"},{"v":"3","t":["Думаю, що ці слова подібні до згаданих у 17-му псалмі. Там Давид каже: полюблю Тебе, Господи, — а потім викладає й причину, з якої полюбив Його, тобто каже: Ти сила моя, твердиня моя, пристановище моє й подібне; а потім: достохвального призву Господа; і далі пояснює лиха, через які призивав Господа й був почутий, бо, каже, обійняли мене болі смертні. І тут знову каже те саме: я полюбив, бо Він почує (замість «почув мене Господь»), коли я молився Йому. Або каже, що Господь ще почує, бо й тепер почув мене. А причиною своєї любові до Бога кладе те, що Господь почує його; далі ж, як і в 17-му псалмі, каже: і в дні мої призиватиму; і потім розповідає й тут ті самі лиха, через які в скорботі знову призвав Господа й був від них визволений; тому й сказав, що полюбив. А згадавши вище про болі смертні й біди адові, Давид пояснює, що вони таке, а саме що вони — скорбота й біль: скорботу й біль, каже, я знайшов. Про болі смертні й біди адові ми сказали ширше в згаданому 17-му псалмі, пояснюючи слова «обійняли мене болі смертні»; там це можеш побачити.","Прим.: Золотоустого: чи помітив ти міцну зброю, чи помітив утіху, що знищує всі лиха, чи помітив, як душа запалюється любов'ю до Господа? Для мене, каже, досить було тільки призвати Бога, щоб звільнитися від зол, що мене оточували. Чому ж ми часто призиваємо й не звільняємося від бід? Бо не призиваємо як слід. Бо Він завжди готовий давати, і Його благість така, що наша порівняно з нею може видатися злістю. Для того й допускає тобі впасти в несподіване лихо, щоб ти призивав Його, щоб старанніше шукав Його. Так і матері, щоб налякати свавільних дітей, надягають різні личини й так змушують їх тікати в їхні обійми, не бажаючи цим їх засмутити, а тільки вдаючись до хитрощів, щоб діти невідступно були при них. Великого Василія: оскільки мене спіткали болі смертні й зустріли мене біди адові, то я так тримав себе, щоб не тільки цих спокус зазнавати мимоволі, а й додавав до них ще набагато більші спокуси добровільно — а саме скорботу й біль, які сам собі добровільно знаходив, а не зазнавав мимоволі. Бо серед останніх, каже, біди адові зустріли мене, а тут скорботу й біль я знайшов. Оскільки там я виявився непоступливим у тому, що навів на мене спокусник, то, щоб показати найревнішу любов до Бога, я додав до цієї скорботи нові скорботи й до болю — біль, не своєю силою протистоячи бідам, а призвавши ім'я Господнє. Так каже й апостол: усе це долаємо силою Того, Хто полюбив нас. А долає той, хто не поступається тяжким болям, що бувають від крайнього нещастя, а перемагає той, хто добровільно, на доказ свого терпіння, накликає на себе неприємності. Хто перебуває в якомусь смертному гріху, той нехай каже: обійняли мене болі смертні. Бо кожен, хто чинить гріх, народжений, каже, від диявола. Отже, коли каже: я чинив беззаконня й був ношений в утробі смерті, тоді мене спіткали адові болі. Як же я вилікував себе? Знайшовши скорботу й біль і вигадавши собі муку, поєднану з покаянням; і так я зважився призвати ім'я Господнє. Ісихія: скорботою й болем назвав покаяння: скорботою — бо воно нагадує гріх, а болем — через труднощі, з якими воно зазвичай звершується, як-от носіння грубої одежі, уживання попелу й чування; знайшовши його, тобто сам набігши на нього, він влучно призивав ім'я Господнє, бо молитва — основа покаяння."],"h":"Обійняли мене болі смертні, біди адові спіткали мене; скорботу й біль я знайшов, і ім'я Господнє призвав"},{"v":"4-5","t":["Господи й Боже, каже, визволяй мене й надалі від майбутніх зол, що можуть мене спіткати. Дивись, читачу, як Давид напучує слухача, представляючи Бога милостивим. Тож не впадай у розпач, грішнику, через свої гріхи. Далі він каже, що Бог і праведний; тож не втрачай бадьорості щодо Його милосердя, але й не будь недбалим і безтурботним, а сподівайся й водночас бійся, як пояснює Золотоустий. Далі, щоб показати, що Бог більше схиляється до людинолюбства, ніж до правди, як зауважує Феодорит, Давид додав і те, що Бог наш милує, сказавши «Бог наш» для відмінності від фальшивих язичницьких богів.","Прим.: Золотоустого: чи бачиш душу, сповнену любомудрості? Як він, залишивши життєве, шукає одного тільки — щоб душа залишилася неушкодженою й не зазнала нічого згубного. Бо коли вона буде в доброму стані, тоді й усе інше відповідатиме цьому; а за її нещасного стану успіх у всьому іншому не може дати нам жодної користі. Тож усе — і діла, і слова — слід спрямовувати до її спасіння. Саме це й означає настанова: будьте мудрі, як змії. Бо як змія, щоб зберегти свою голову, віддає всю решту тіла, так і ти за спасіння своєї душі маєш віддавати все інше. Зауважимо тут, що блаженний Феофілакт, пояснюючи євангельські слова, сказані Господом: душа Моя тепер стривожилася, і що Мені сказати? Отче, спаси Мене від цієї години (Ін. 12:27), а також такі апостольські: Він за днів Своєї плоті з сильним голосінням і сльозами приніс молитви й благання Тому, Хто міг спасти Його від смерті (Євр. 5:7), — каже, що Давид у цьому псалмі пророкує про ці слова Господа й апостола; тому й каже: і в дні мої призиватиму; обійняли мене болі смертні, біди адові спіткали мене, і ім'я Господнє я призвав: Господи, визволи душу мою.","Прим.: Феодорита: згадавши про милість двічі, про правду сказав один раз, і цим показав, що Бог більше схильний до людинолюбства; бо воно перемагає суд правди, якою Він користується лише як засобом. Великого Василія: милосердя — це співчуття, яке буває в тих, хто має до когось любов, до тих, хто надто принижений. Так ми співчуваємо тому, хто, бувши раніше дуже багатим, дійшов до крайньої бідності, і тому, хто раніше вирізнявся красою й досконалістю тіла, а потім підупав від соромних пристрастей. Тож оскільки й ми колись були славні, коли перебували в раю, а потім стали безчесні й принижені через падіння, то Бог милує нас, бачачи, чим ми стали й якими були раніше; тому голосом Свого милосердя Він і до Адама взивав: Адаме, де ти? Бо Той, Хто знав усе, не потребував повідомлення, а хотів, щоб той зрозумів, з якого яким він став. «Де ти?» — замість того щоб сказати: куди ти скотився з такої висоти? Орігена: оскільки Господь милує з правдою, то Він милостивий і праведний. Саул, милуючи Агага, у цій милості не був праведний. І якби всяка милість була праведна, то закон не казав би про деяких: не вигороджуй убогого на суді (Вих. 23:3). Неназваного автора: Бог, як милостивий, не відвертає лиця від грішника, що молиться; а як праведний, Він не інакше приймає його, як з покаянням."],"h":"О Господи, визволи душу мою. Милостивий Господь і праведний, і Бог наш милує"},{"v":"6","t":["Тут у грецькому мається на увазі дієслово «є»: Господь є Охоронцем немовлят. Давид хвалить особливий Божий промисел щодо немовлят: бо якби, за словами Василія та Золотоустого, цей промисел не охороняв малих дітей, а особливо поки вони в пелюшках, то їх легко вбили б змії, скорпіони й багато інших тварин, і вони легко калічилися б, падаючи в рови, колодязі, урвища й інші небезпечні місця. Дехто з Феодоритом розумів ці слова про немовлят, коли вони ще в утробі матері, рухаючись у темних і вологих вмістилищах утроби, як рухаються в морській глибині риби, так що там вони не мають змоги навіть дихати, бо починають дихати тоді, коли народяться. Потім, вийшовши з гарячої утроби в це холодне повітря, до якого зовсім не звикли, вони ні на короткий час не могли б залишитися живими, якби їх не охороняв Божий промисел. Інакше немовлятами можеш уявляти новонасаджених і початківців у чесноті, яких Бог охороняє Своїм промислом через їхню недосвідченість, до часу, коли вони поступлять і зміцніють для боротьби з пристрастями й невидимими ворогами — бісами.","Прим.: Феодорита: отроками називає відроджених у Христі дією Святого Духа й тих, хто за вченням Ісуса має властивості отроків, бо вони навернулися й живуть, як отроки, яких Сам Господь охороняє, не дозволяючи ворогам нападати на них, бо вони ще не досягли часу подвигу.","«Упокорився я, і Він спас мене»","Я страждав, каже, від спокус; тому Він спас мене, тобто Господь визволив мене від них; бо Він же допустив мені страждати, щоб я став розважливішим, а знищив спокусу, щоб я пізнав Його благодать і промисел про мене; і, за Золотоустим, з обох боків зробив мені благодіяння. А втім, можна розуміти й інакше: Бог спасає тих, хто вдосконалився в чесноті смирення.","Прим.: З Василієм Великим ці слова можеш розуміти так: оскільки я упокорився, поводився й жив, як немовля, приймаючи Царство Небесне, як отрок, і незлобивістю привів себе до дитячого смирення, то Охоронець немовлят Господь спас мене від болів смертних і бід адових. Не сказав: не допустив упасти в біди, — а що й після падіння спас. Золотоустий: тут подвійна подяка — і за те, що допустив упасти в біди, і за те, що не залишив того, хто впав; і так і тим, і іншим зробив благодіяння. І те, й інше — рід благодіяння, і перше не менше за друге, а якщо сказати щось дивне, то й більше, бо через друге даровано свободу від лих, а через перше душа стала розважливішою."],"h":"Охороняє немовлят Господь"},{"v":"7-8","t":["Декому Давид у цих словах видається таким, що спонукає самого себе повернутися до спокою й свободи від тих спокус, яких зазнавав досі; бо він утішає себе тим, що тоді був звільнений і визволений від очікуваної смерті, від сліз, які проливав через велику скорботу, і від сітей, поставлених йому ворогами, якими він часто був уражений. А якщо хтось сприймає ці слова у вищому розумінні, то під спокоєм, згідно із Золотоустим, може розуміти відхід душі праведника, який звільняє його від усякого смутку. Бо це її розлучення й упокоєння — благодіяння від Бога для праведних людей, бо вони через це звільняються від тягаря й інших тілесних недуг; тому й Павло каже: бо ми, що в цьому наметі, стогнемо під тягарем (2 Кор. 5:4); і ще: бажаю відійти й бути з Христом, бо це набагато краще (Флп. 1:23). Отже, ці слова личать тим праведникам, що відлучаються від цього тяжкого й багатотрудного тіла й упокоюються в небесних оселях. Тому й Давид, сказавши, що Господь зробив тобі добро, додав, що Він вирвав, тобто звільнив його душу від смерті, або від мого гріха, що є душевною смертю, бо умертвляє дії душі в чесноті. Він звільнив також і мої очі від сліз, так що вони вже не плачуть через численні й часті скорботи; звільнив і мої ноги від перешкод і спотикань, які клали мені мої видимі й невидимі вороги, що зловмишляли на мене.","Прим.: Золотоустий додає й таке: хоча смерть внесена у світ гріхом, але Бог ужив її нам на благодіяння; і вона, оскільки дає нам свободу від зол і часто проводжає до горішнього життя, — не знаю, чи може власне зватися смертю, коли вона лякає більше своїм іменем, ніж самою справою. А якщо вона й видається жахливою, то видається такою через неміч тих, хто має про неї таке поняття. Ні, не смерть завдає гіркоти, а свідомість пороків у совісті. Тож перестань бути грішником, і тоді смерть буде для тебе бажаною. Слова Василія: спокоєм своїм праведник називає горні оселі, які дістане на віддяку за свої подвиги. Тому добрий подвижник відносить до себе ці втішні слова, подібно до Павла кажучи: добрим подвигом я подвизався; а тепер готується мені вінець правди. Бо вічний спокій призначений тим, хто законно подвизався в цьому житті, і віддається не за діла як борг, а з милості великого Бога даровується тим, хто на Нього сподівався. Добре сказав «до спокою твого», бо він твій власний, а не чужий: святі дістають приготовані їм Богом блага як свій власний набуток. Золотоустого: «і ноги мої від спотикання» — це більше за попереднє, бо ми звільнені не тільки від смутку, а й від спотикань і злих задумів. Отже, той, хто відійшов з добрими подвигами й досяг пристані, той уже став на камені; усі перешкоди зникли; уже ніде немає неспокою й шуму, а перебуває в безперервній славі той, хто так звідси відійшов. Ісихія: спокій душі — це припинення гріхів, бо її непокоїть гріх і розбиває всі її сили. Тому, вважаючи хрещення свободою від гріхів, Давид назвав його водою спокою. Отже, він радить душі, що блукала в гріхах, повернутися до спокою, який дає хрещення або сльози покаяння. Знову Василія: зображує майбутній спокій у порівнянні з земними благами. Тут обійняли мене болі смертні, а там вирвав душу мою від смерті. Тут очі від скорботи ллють сльози, а там немає сліз, бо Бог зітре всяку сльозу з кожного обличчя (Іс. 25:8). Тут велика небезпека спотикання; тому й Павло казав: хто думає, що стоїть, нехай стережеться, щоб не впасти; а там тверді основи, життя незмінне, немає небезпеки бути захопленим гріхом."],"h":"Повернися, душе моя, до спокою твого, бо Господь зробив тобі добро; бо вирвав душу мою від смерті, очі мої — від сліз і ноги мої — від спотикання"},{"v":"9","t":["Країна живих — це небо, або майбутній світ, де ніхто не вмирає; а цей світ — країна й місце тих, хто вмирає. Отже, каже, буду благоугоджати в тій безсмертній країні, безперешкодно служачи Богові зі святими ангелами, не маючи підступників. Або сказав «буду благоугоджати» замість «буду визнаний угодним Богові». Утім, ці слова пояснено й в іншому місці, у 55-му псалмі, де написано: бо Ти визволив душу мою від смерті, очі мої від сліз і ноги мої від спотикання; буду благоугоджати перед Господом у країні живих.","Прим.: Феодорита: країною живих називає не тутешнє життя, у якому плач, і ридання, і хвороби, і смерті, і гріхи, і нещастя, а вільне від усього подібного, у якому володіння чеснотою безпечне й де без трудів здобувається багатство правди.","Прим.: Золотоустого: добре сказав «у країні живих». Бо те власне життя вільне від смерті, бо має блага без домішки зла. Бо останній, каже, ворог знищиться — смерть. Євсевія: цей світ і сам смертний, і є місцем тих, хто вмирає; і душа, ув'язнена в смертному тілі й перебуваючи в цьому житті, не в країні живих, а ніби напівмертва, бо зодягнена у власному розумінні в мертве й природно тлінне тіло, так що вся людина складена з мертвого й живого. Отже, перебування на землі й життя в тлінному тілі — не перебування в країні живих; тому праведник знає, що тутешня країна чужа для його душі, бо душа не з землі взята й не в землю відійде, а належить до країни живих. Василія: країна живих — та, у якій пророк обіцяє особливо благоугоджати Богові, бо ні в чому зовнішньому не знаходитиме перешкоди; це та країна живих, у якій немає більше ночі, немає сну — цієї подоби смерті; немає їжі й питва — цих підкріплень нашої немочі; немає жодного зовнішнього нещастя; а країна живих, що не вмирають через гріх, а насолоджуються істинним життям у Христі."],"h":"Буду благоугоджати перед Господом у країні живих"}],"115":[{"v":"0","t":["Алилуя.","І цей псалом, як і попередні, — подячний Богові; тому має той самий напис."]},{"v":"1","t":["Великий Василій каже, що оскільки пророк Давид наприкінці попереднього псалма сказав: буду благоугоджати перед Господом у країні живих, — то тепер на початку цього псалма каже: я повірив тому, що пророкував в іншому псалмі, тобто повірив, що буду благоугоджати перед Господом у країні живих, тому й казав це. Бо я не тілесними очима бачив ту країну, а, за Феодоритом, віра вказала мені її. До того ж і в 26-му псалмі ще сказав: вірую, що побачу добра Господні на землі живих, хоча там це пояснено в іншому значенні.","«А я впокорився дуже»","Я, каже, одержавши від Бога таке передбачення, що буду благоугоджати Богові, дуже впокорився, вважаючи себе недостойним цього великого дару й боячись, щоб не загордитися й не втратити такого великого дару.","Прим.: Слова Великого Василія: віра має передувати словам про Бога — віра, а не доказ. Віра, що сильніша за логічні методи, захоплює душу до згоди. Ах, якби й мені дано було увірувати гідно, щоб я сказав тепер цій великій Церкві Божій п'ять слів розумом моїм! І нехай ніхто не глузує з нашого вчення за те, що ми змушуємо слухачів погоджуватися з нашими словами без доказів. Бо початки в кожній науці неминуче подаються учням без доказів. І взагалі душа, що приступає до мови без віри, базікатиме марно, бо не заклала для слова жодної основи. Отже, початок мудрого слова — віра, що міцно вкоренилася в серці того, хто говорить. Потім Давид указує, як ми можемо досягти досконалої віри, такими словами: а я впокорився дуже. Бо хто не впокорив свого розуму й не каже, подібно до апостола: брати, я не вважаю себе таким, що вже досяг, а власним розсудом міряє незбагненне, той не може казати про себе: я увірував, тому й заговорив; бо не може додати й наступних слів: а я впокорився дуже. Золотоустого: думку, що міститься в цих словах, апостол пояснює коринтянам: маючи, каже, той самий дух віри, як написано: я увірував, тому й заговорив, — і ми віруємо, тому й говоримо; тут духом віри називає налаштування, що походить від віри, або дух, який дається від Бога тим, хто має віру. А слова «я увірував, тому й заговорив» згідні з такими: серцем віруємо для праведності, а устами сповідуємо для спасіння (Рим. 10:10)."],"h":"Увірував я, тому й заговорив"},{"v":"2","t":["Захопленням, тобто нестямою, Давид називає тут вражене здивування, за словами Великого Василія: бо я, каже, вражений і приведений у подив тією дивною країною живих, яку побачив з допомогою Святого Духа, ясно сказав, що кожна людина, що перебуває в цьому світі, оманлива щодо людського блаженства, яке й Григорій Богослов назвав оманливим добробутом, бо воно не тривале, а швидко минає й зникає, як оманливий сон, що не має нічого дійсного. Бо все людське, за словами Екклезіаста, — марнота марнот, бо легко змінюється й гине; а блага, що в тій країні живих, — істинні блага, бо сталі, незмінні й безсмертні.","Прим.: Григорій Ніський, сприймаючи ці слова у вищому значенні, каже так: що таке істинна краса? Кожному потрібні власні очі, щоб міг бачити ту красу, яку він побачив з якогось божественного дару й натхнення і якою був приведений у невимовний у таїні совісті подив. А хто побачив її, той не зазнає втрати. Добре, мені здається, вказав на цю трудність Давид, який, колись піднісшись розумом, силою Духа в тому блаженному захопленні побачив незбагненну й невимовну красу, а побачив її, безперечно, настільки, наскільки можливо людині бачити, коли була виведена поза покрови плоті. Але коли захотів сказати щось відповідне баченому, то вимовив відомі всім слова, що кожна людина — брехня; а це, на моє розуміння, означає, що хто силкується словами висловити невимовне, той справді брехливий — не з ненависті до істини, а через безсилля мови. Великого Василія: утім, пророк тут не суперечить сам собі, у чому деякі софісти намагаються його викрити, твердячи: якщо кожна людина брехлива, а Давид також людина, то, очевидно, і сам він був брехливий; а якщо брехливий, то йому не слід вірити в тому, що він стверджує. А правда така, як ми скажемо. Бо людьми тут звуться ті, ким ще володіють людські пристрасті; а хто став уже вище тілесних пристрастей і досконалістю розуму перейшов до ангельського стану, той, коли говорить про людські справи, очевидно, виключає себе з ряду інших людей. Бо не брехливий той, хто сказав: я сказав: ви боги! Звісно, якщо кому іншому, то Давидові личить таке найменування. Бо й сином Всевишнього є той, хто чеснотою споріднився з Богом і не вмирає, як людина, а має Бога, що живе в ньому. Зауваж, що Акила переклав: я сказав у моєму остовпінні: кожна людина — брехня; а Феодотіон: кожна людина знемагає; Симмах: я сказав у збентеженні: кожна людина оманлива. І я не без причини вказав на всі ці пояснення, а щоб показати, що людський добробут називає брехнею, бо він дуже швидко руйнується й не має жодної тривалості (слова Феодорита); тому й Соломон, хоча сам жив у всякому добробуті, починаючи говорити про те, які людські справи, робить такий початок: марнота марнот, усе марнота."],"h":"А я сказав у захопленні моєму: кожна людина — брехня"},{"v":"3","t":["Яку, каже, віддяку зроблю Богові, Який, понад інші незліченні благодіяння, зроблені мені, нікчемному, дарував і цю благодать — бачити в захопленні ту невидиму країну живих? Вислів «віддав» ужито замість «дав», як ми зауважили й у 7-му псалмі, пояснюючи слова: якщо я віддав тим, хто віддає мені злом.","Прим.: Слова Золотоустого: це каже, приймаючи на себе обставини полонених. Багато Ти, Владико, мені благодіяв. Чим мені віддати Тобі? Прийми посудину з возлиянням, і я возлию її Тобі за спасіння народу — жертву, так зване возлияння спасіння; і ім'я Твоє призову, і віддам ті обітниці, які я обіцяв за спасіння народу. Така налаштованість до вдячності: вона полягає в тому, щоб шукати всіх можливих нагод принести щось Благодійникові за одержані від Нього блага, і, віддавши все, вважати себе безсилим чимось Йому віддячити. Василія Великого: тут Щедродавець зветься не тим, що дає, а тим, що віддає, ніби не Він починав дарувати, а тільки віддавав тим, хто почав це робити раніше; бо вдячність тих, хто одержує, Він зараховує Собі за благодіяння. Так Він, і даючи тобі майно, просить у тебе милостині рукою убогих; а коли одержить Своє, твій дар цілим повертає тобі, ніби за твоє власне."],"h":"Що віддам Господеві за все, що Він віддав мені?"},{"v":"4","t":["Оскільки Давид раніше не знайшов гідної віддяки, яку міг би принести Богові, то тут каже, що візьме чашу спасіння, якою називає мученицьку смерть за Христа, за розумінням Василія. Так і Христос у святому Євангелії назвав цю смерть чашею, сказавши синам Зеведеєвим Якову та Іоанові: чи можете пити чашу, яку Я питиму? (Мт. 20:22). Давид назвав її спасенною тому, що смерть за Христа ще більше спасає й оживотворює тих, хто вмирає за Нього. Отже, він каже: я помру за Христа, маючи спрагу до смерті за Нього, Який сподобив мене стількох і таких великих благодіянь, як Єдинородний Син Божий. І ім'я Христове призову, щоб Він дарував мені благодать померти за Нього. Отже, божественний Давид, наскільки це залежало від нього і від його волі, помер з любові до Христа.","Прим.: Золотоустого: отже, він каже таке: у мене немає нічого гідного, що я міг би принести. Але що маю, те приношу — жертву подяки Богові, і оспіваю Його за спасіння. Василія: у нас не може бути іншої віддяки за одержані від Господа блага, як прийняти за Нього смерть і наслідувати Владику. Ця смерть властива й тим, хто дуже дорогий Богові; так страждання в подвигах за благочестя й протистояння гріхові до смерті назвав чашею. Отже, чашу спасіння прийму, тобто зі спрагою піду до кончини через мучеництво, як той, хто має випити питво безсмертного життя, як той, хто вважає муки, що завдаються мені за подвиги благочестя, спокоєм душі й тіла, а не болями. І Феодорит: також чашею спасіння називає смерть за благочестя. Цю чашу й тут змушують себе випити мужні й доблесні подвижники благочестя. А Афанасій чашею спасіння називає причастя таїнств. Подібно до цього каже й Золотоустий. Марко Ефеський дивується, чому цей вірш Давида, тобто «чашу спасіння прийму й ім'я Господнє призову», співається як причасний на свята Богородиці. Потім, розв'язуючи подив, каже: це личить і всім дням, і особливо причастю; але співається власне на честь Богородиці не через перше півстишшя, тобто слова «чашу спасіння прийму», яке, як сказано вище, спільне для всіх днів, а через друге, що містить слова «і ім'я Господнє призову»: це пророцтво, що стосується Богородиці й на Ній збувається. Бо тоді Вона призвала ім'я Господнє, коли сказала: величає душа Моя Господа, і зрадів дух Мій у Бозі, Спасі Моїм; бо відтепер ублажатимуть Мене всі роди, бо вчинив Мені велике Сильний, і святе ім'я Його. Не помилиться й той, хто прийме цю чашу за божественну благодать Духа, бо вона дає веселість і захоплення, як і в Давида сказано: чаша Твоя напуває мене, мов найкраща; наситившись нею, а краще — сповнившись, Богородиця й виголосила таку пісню."],"h":"Чашу спасіння прийму й ім'я Господнє призову"},{"v":"5","t":["Я, каже, за своїм обов'язком віддам Богові ті обітниці, які безстрашно дав Йому перед безліччю народу, бо мав незабаром відійти з цього життя.","Прим.: Слова Василія: ці, каже, обітниці — випити чашу спасіння — я готовий виконати при свідченні всього народу."],"h":"Молитви мої Господеві віддам перед усім народом Його"},{"v":"6","t":["Я, каже, радію тому, що помру, бо смерть присвячених і відданих Богові дорогоцінна. Якщо й життя таких людей дороге, то тим більше смерть, яка проводжає їх до їхнього Владики й Бога. Бо віддані Богові при своїй смерті дістають від Нього честь: їх проводжають і зустрічають святі ангели.","Прим.: Того ж Василія Великого: справді дорога смерть святих. Бо коли душа, очищена й прославлена подвигами за благочестя, стає перед Суддею, сяючи надзвичайною красою чесноти, то як не дорога в очах Господа смерть такої людини? Тож не оплакуймо відходу святих мужів звідси, а краще оплакуймо дні народження й появи в цьому житті. Бо вхід у цей світ буває з безчестям, скверною й смородом; а вихід і звільнення з цього життя чесні й славні — не всіх людей, а тільки тих, хто свято й старанно провів теперішнє життя. Коли помирали по-юдейськи, тобто природною смертю, тоді трупи їхні були гидкі; а коли смерть була за Христа, то останки їхні, тобто мощі, дорогі. І нині хто торкається кісток мученика, дістає певне освячення, що подається благодаттю, яка невідступно перебуває в цьому тілі. І Пахимер у примітках на Діонісія каже: дорога перед Господом смерть святих не просто тому, що вона смерть і розлучення душі з тілом, а тому, що святі мужі закінчують життя у святості. Феодорита: а якщо вона чесна й для Бога, то для кого зі святих не гідна шани? Інший каже: чи бачиш, що чашею спасіння назвав смерть за сповідання Бога? А яка вона дорога, показує честь, що віддається мученикам по всьому всесвіті. І слова Господні показують те саме: хто визнає Мене перед людьми, того й Я визнаю перед Отцем Моїм, що на небесах."],"h":"Дорога перед Господом смерть преподобних Його"},{"v":"7","t":["Господи, каже, я присвячений і відданий Твоїй владі; тут двічі назвав себе рабом Божим і цим показує, що іменує себе рабом Божим з радістю і, за словами Золотоустого, відкриває й сповідує це без жодного сорому. До того ж, сказавши, що він син Божої рабині, тобто своєї матері, цим показує, що він раб Божий від батьків; а згадав ім'я матері своєї, а не батька, довільно. Або сказав це тільки тому, що діти рабинь були дуже дорогі для своїх панів.","Прим.: Слова Золотоустого: говорить не про загальне рабство, а про таке, що поєднане з великою прихильністю й любов'ю, бо він був запалений доброзичливістю, яка є для нього найбільшим вінцем і світлішим за всяку діадему; тому й Бог ставить це на найбільшу похвалу, коли каже: Мойсей, раб Мій, помер. Євсевія: двічі назвав себе рабом, щоб разом з природним рабством, яким ми, сини рабині, тобто природи, зобов'язані Творцеві, виразити й добровільне рабство, з яким служать тільки праведники."],"h":"О Господи, я раб Твій, я раб Твій і син рабині Твоєї. Розірвав Ти пута мої"},{"v":"8-10","t":["Ти, каже, Господи, розірвав, тобто розсік, пута моїх гріхів мечем покаяння. Тому я принесу Тобі жертву хвали й славослів'я, що є породженням мого серця. Де ж принесу цю жертву? На жертовник моєї душі. І призову ім'я Твоє, Господи, щоб воно допомагало мені в цій духовній жертві. Тому й знову каже, що виконаю за своїм обов'язком ті обітниці, які я дав Тобі, Господи! Це сказав і вище, і тут — для більшого підтвердження своїх слів цим повторенням. Далі вказує й місце, у якому віддасть свої обітниці: це двори дому Господнього; бо Мойсеева скинія мала різні двори, і вона тоді була в Єрусалимі.","Прим.: Золотоустого: які це пута, як не гріхи? Бо кожен зв'язується путами своїх гріхів. Або в історичному значенні тут розуміються пута смутку. Отже, є й добрі пута, якими зв'язуватися — добра справа. Так каже про союз любові, що вона — союз досконалості; і ще: в'язень Ісуса Христа.","Прим.: Василія: досягнувши досконалості, Давид відмовляється від кривавих жертв, а обіцяє звершувати жертви хвалою. Він немовби так каже: оскільки Ти, зійшовши до аду, звільнив мене від пут гріха й розв'язав людство, що було в путах смерті й трималося в неприступних кайданах аду, то я принесу Тобі жертву не з чотириногих, що мають роздвоєні копита й жують жуйку, ні з чистих птахів, ні з чистого борошна, змішаного з олією, бо це приноситься Владиці від землі; а з того, що становить власне моє надбання й породження мого серця, я принесу Тобі від нього славослів'я, як від якогось жертовника — від мого розуму, бо Ти не вимагаєш тілесних жертв, які щедро приносять багаті люди, а сповідання від любові й серця, у якому можуть нарівні брати участь усі охочі. Інший каже, що й той, хто бере участь у новозавітних таїнствах, тобто в спасенних Тілі й Крові та в безкровній і словесній жертві, що приноситься Богові хвалою й подякою, може сказати: чашу спасіння прийму й жертву хвали Тобі принесу, а не жертви, що були за Мойсея. Золотоустого: Тобі принесу жертву хвали, тобто дякуватиму, співатиму. Подяка приємніша Богові за всяку жертву; це річ найщедріша, якою може бути багатий і найбідніший. Василія: приношу, каже, Тобі хвалу перед усім народом; принесу не таємно десь, як той, хто соромиться, і не в прихованому місці, тікаючи від докорів нечестивих, а звершу її всенародно, взявши в спільники цього богослужіння весь народ. Принесу у дворах дому Господнього. Зважте на це ви, що залишаєте зібрання, а збираєтеся в звичайних домах, ви, нещасні, відірвані від чесного тіла! І за давнім служінням не дозволялося кожному влаштовувати жертовник, а один був указаний тим, хто бажав приносити жертву. Феодорита: можна й з цього зрозуміти, що й ті, над ким мав владу закон, виконуючи його духовніше, ставили розумні жертви вище за безсловесні, і цим наперед зображували нам Новий Завіт. Цей псалом личить і всім доблесним мученикам.","Так пояснюється цей псалом у зв'язку з попереднім псалмом. Залишається тепер викласти тут пояснення Золотоустого. Цей божественний отець каже, що Давид, передбачаючи страждання юдеїв у вавилонському полоні й згадуючи про повернення й свободу, яку вони мали знову здобути, каже в цьому псалмі: я повірив, що юдеї, мій рід, мали бути поневолені й знову звільнені, дізнавшись про це з напучення Святого Духа; тому й говорив про це в різних псалмах. Я впокорився, тобто багато страждав, сумуючи через полон мого роду. Але я сказав у захопленні моєму: кожна людина — брехня, тобто сказав у моєму смутку; бо смуток приводить сумного до виходу з прямого й непохитного розуму, а коли сильніше розіллється в людині, тоді робить її безчутною. А думаючи особливо про неміцність людського щастя й бачачи це в переміні щастя юдеїв, які, наскільки були раніше щасливі, настільки потім стали нещасні, — думаючи, кажу, про це, він сказав, що справді всяке людське благо оманливе, бо не таке, щоб могло тривати. Далі: оскільки сподіваюся, що мій рід дістане повернення й свободу, то я дуже радію й кажу: що віддам Господеві за все, що Він віддав мені? Бо благодіяння своєму родові Давид вважав своїм власним благодіянням.","Багато, каже, Бог мені благодіяв; але що віддам Йому? А ці слова означають велику радість і душевну вдячність Давида. Чашу спасіння прийму, тобто, каже, візьму чашу з возлиянням і виллю її на жертву перед Богом за спасіння мого народу. Бо в юдеїв були різні види приношень і жертв, і серед них — возлияння спасіння. І ім'я Господнє призову на спасіння мого народу, тобто виконаю перед Господом ті обітниці, які я дав за лихих обставин для свого спасіння. «Дорога перед Господом смерть преподобних Його» — це настанова про те, що смерті тих, хто служить Богові, Він віддає честь присутністю ангелів і багатьох святих, щоб віддати велику честь тим, хто вмирає. А в тих, чия смерть шанована, і життя дуже чесне, бо в житті, вправляючись у чеснотах, вони служили своєму Владиці. «Господи, я раб Твій і син рабині Твоєї» — цими словами виражає не загальне рабство, за яким усі — раби Божі, бо все, каже, служить Тобі (Пс. 118:91), а служіння добровільне, з прихильності й любові. Давид вважає найбільшою гідністю бути рабом Божим і прикрашатися цим рабством більше, ніж царством. А вислів «син рабині Твоєї» Золотоустий прийняв у тому самому значенні, яке дали йому ми.","«Ти розірвав пута мої» — це означає пута смутку й спокус, які мали наді мною велику владу, зв'язуючи й тиснучи мене. Золотоустий пояснює це так, як пояснили й ми. Я принесу Тобі жертву хвали за розірвання моїх пут і спокус, яке Ти вчинив мечем Твого людинолюбства; жертвою хвали називає славослів'я й подяку. «І ім'я Господнє призову», тобто ім'я Господа призиватиму й під час інших спокус, які спіткають мене й надалі, бо я випробував, яку велику силу має славне й страшне ім'я Боже. Решту слів Золотоустий пояснює так, як пояснили й ми. Нарешті Давид віддав молитви перед усім народом не з гордості й хвастощів, а щоб привести до своєї ревності й усіх юдеїв і взяти їх у спільники цієї віддяки. А подяка Богові, яку легко здобути й яку може мати й найнещасніша та найбідніша людина, приємніша Богові за всяку жертву."],"h":"Тобі принесу жертву хвали й ім'я Господнє призову. Молитви мої Господеві віддам перед усім народом Його, у дворах дому Господнього, посеред тебе, Єрусалиме"}],"116":[{"v":"0","t":["Алилуя.","І цей псалом — з-поміж подячних. Він закликає всі народи до славослів'я й подяки Христові за такі великі благодіяння й милості, виявлені всім народам домобудівництвом Його втілення."]},{"v":"1","t":["Приносьте, каже, всі народи, що увірували в Христа, пісні й славослів'я Господеві за те, що Він указав вам дорогу і ви вийшли з темряви омани й ідолопоклонства й переселені в царство світла, істини й богопізнання. І всі люди, хваліть Господа. Тут, каже, те саме, що сказав вище, — щоб примножити славослів'я Христові. Або людьми називає тих юдеїв, що увірували в Христа. Або називає всіх людей загалом, бо всі загалом мають дякувати Христові, Який став людиною для спасіння всіх людей і благоволив прийняти спасенні страждання, а особливо для спасіння всіх юдеїв; бо Я, каже, посланий тільки до загиблих овець дому Ізраїлевого (Мт. 15:24).","Прим.: Слова Євсевія: дуже ясно, що в цих словах міститься пророцтво про блага в Церкві й передвіщення тієї проповіді, що охопила весь усесвіт. Бо цей псалом закликає не два чи три народи, а всю землю й море; і це збулося тоді, коли засяяло Христове пришестя. Бо тоді, за Феодоритом, Він дав засоби до спасіння всім народам, уживши на службу цьому благодіянню святих апостолів, які, обійшовши весь усесвіт, розвіяли морок невігластва й показали Сонце правди: ідіть, каже, навчіть усі народи. До цього той самий Феодорит додає: оскільки юдеї розпорошилися по всьому всесвіті й навчали про єдиного Бога, і не жили вже в одній Палестині, і не перебували в одному народі, підкоряючись одному цареві, а розсіялися в усіх народах, то влучно називає їх не народом, а народами. Або, можливо, як каже Євсевій, так називає й тих, хто увірував з народів, згідно з написаним у Захарії: і прибіжать багато народів до Господа й стануть Його народом (Зах. 2:11). Бо досі, бувши язичниками, вони не були Його людьми; але, змінивши колишнє життя, вони стають Його людьми. Зауваж, що ці слова апостол Павло наводить у Посланні до римлян, щоб показати їхнє тодішнє виконання. Він так каже: а язичники — з милості, щоб славили Бога, як написано: хваліть Господа, усі язичники, і прославляйте Його, усі народи (Рим. 15:9–11)."],"h":"Хваліть Господа, всі народи, прославляйте Його, всі люди"},{"v":"2","t":["Милість, каже, Господня стала сильною й твердою й надзвичайно вилилася на всіх людей з Його великого людинолюбства, хоча деякі люди й відвернулися від неї й не захотіли її прийняти. Тут Давид зараховує й себе до тих, хто прийняв Божу милість, як робить і в інших псалмах, долучаючи й самого себе до християн з народів і вважаючи себе одним з тих, хто увірував у Христа. А істина Господня, що перебуває повік, — це євангельська істина, та, яку Христос передав апостолам; бо закон був тінню євангельської істини, за словами Золотоустого; тому, коли з'явилася євангельська істина, тінь закону минула, як зникають перший начерк і накреслення тіней ікони, коли малярі наводять на неї справжні барви; бо благодать, каже, і істина прийшли через Ісуса Христа (Ін. 1:17).","Прим.: Золотоустого: називає й причину спасіння: не своїми добрими ділами й не своєю відвагою в житті, а одним людинолюбством вони спаслися. Бо, за словами Феодорита, з одного людинолюбства Він звершив наше спасіння. Так і блаженний Павло сказав: не з діл праведності, які ми вчинили, а з Своєї великої милості Він спас нас; і ще: благодаттю ви спасенні. Влучно сказано й у пророчих словах, що народи не зазнали б такої переміни, якби Божа милість не була сильніша за наші гріхи, якби вона не була міцніша за нашу лиху вдачу й не перемогла всякого забобону й омани. Ісихія: тобто милість, що утвердилася в нас, була співвічна істині. У багатьох місцях ці імена (милість і істина) відносяться до Спасителя, як і в такому: Бог послав милість Свою й істину Свою і визволив душу мою з-посеред левенят. Тож вона, засяявши в людському роді, кличе всі народи й усіх людей до хвали, навчаючи дякувати Отцеві, що утвердив Свою милість і продовжив Свою істину повік. Золотоустого: утвердилася милість Його над нами, тобто вкорінена, стала міцною й твердішою за камінь; до того ж щодня зростає."],"h":"Бо утвердилася милість Його над нами, і істина Господня перебуває повік"}],"117":[{"v":"0","t":["Алилуя.","І цей псалом — подячний Богові за благодіяння, які Давид одержав від Нього.","Прим.: Слова Феодорита: юдеї цією піснею приносять подяку Богові після повернення з Вавилону, коли сусідні й інші зухвалі народи зібралися проти них, а потім були винищені карами, посланими від Бога. А оскільки в них прообразовано нас, то цей спів стосується тих, хто увірував з язичників. Ісихія: Давид часто прославляє сповідання, знаючи, що в ньому дано грішникам найбільшу допомогу й ліки від душевних ран."]},{"v":"1","t":["Ті самі слова Давид сказав і в 105-му псалмі, і там вони пояснені. Сповідуйтеся, каже, перед Господом у своїх гріхах, бо Він милостивий і не пам'ятає зла тим, хто сповідається, і милість Його, за словами Євсевія, стала й безперервна до тих, хто кається."],"h":"Сповідуйтеся Господеві, бо Він благий, бо повік милість Його"},{"v":"2-4","t":["Нехай, каже, простий ізраїльський народ, і рід Ааронів, тобто священичий, і всі, що бояться Господа, тобто прибульці, що прийшли до віри з язичників, скажуть; що ж скажуть? Що Господь милостивий до тих, хто сповідається, і що милість Його стала до тих, хто приносить покаяння; бо всі вони дістали від Бога у слушні часи й різними способами благодать і милість. Він і тут поділив юдеїв на три частини, як поділив їх і в 113-му псалмі словами, що читаються так: дім Ізраїлів надіявся на Господа.","Прим.: Слова Євсевія: у згаданих тут трьох розрядах середнє місце займає священичий чин, так що ніби з одного боку поставлено Ізраїль, з іншого — тих, хто боїться Господа, а посередині — священиків, яких назвав домом Аароновим. Золотоустого: що означає «повік милість Його»? Безперестанно й безперервно в усі часи вона являється в усьому блиску. А якщо небагато хто бачить її, то це буває через безсилля їхнього мислення. Так не можуть дивитися на сонце й ті, хто хворий на очі. Феодорита: за пришестя Христове найбільше мають дякувати юдеї. Бо хоча вони зазнали лих, але не через Того, Хто прийшов, а через своє нерозуміння. Неназваного автора: оскільки євангельська благодать вилилася на всі народи, серед яких був і народ обрізання, і то становив головний народ, то в цих словах влучно першим закликається до сповідання він, а за ним і ті, хто прийшов до Євангелія з язичників; це згідно й з цими словами: спершу юдеєві, потім і еллінові.","Склавши з усіх юдеїв один хор і звелівши їм дякувати Богові (бо сповідання означає й подяку) і казати, що Він благий і що повік милість Його, трохи нижче Давид викладає їм і свої обставини: бо юдеям належало дякувати Богові й за свого царя Давида, адже він вів війну за них і зазнавав спокус з любові до них, і від усього цього Сам Бог дивовижно його визволяв."],"h":"Нехай скаже дім Ізраїлів, що Він благий, бо повік милість Його. Нехай скаже дім Ааронів, що Він благий, бо повік милість Його. Нехай скажуть усі, що бояться Господа, що Він благий, бо повік милість Його"},{"v":"5","t":["Я, каже, призвав Господа, коли був у тісних обставинах і спокусах; і Господь не тільки просто вислухав мене, а й на простір, тобто з тісноти вивів мене до спокою й свободи. Так він каже й у 4-му псалмі: у скорботі Ти дав мені простір; там і шукай пояснення.","Прим.: Золотоустого: чи бачиш, яка благість і людинолюбство? Не сказав: я був того вартий; не сказав: я вчинив праві діла, — а тільки: я призвав; і однієї молитви досить було для звільнення від лиха; це кажеться й про те, що сталося в Єгипті: Я добре бачив страждання народу Мого й зійшов, щоб визволити їх. Не сказав: Я бачив чесноту народу Мого, а гноблення. Чи бачиш, як милосердний Отець допомагає за одне тільки лихо? Тому й праведник, що був у скорботі, просить не того, щоб не зазнавати її, а щоб міг великодушно й спокійно її перенести. Орігена: той, хто йде тісною й скорботною дорогою, у скорботі призиває Господа; і тоді як той, хто йде широкою, і не призиває, той, хто призиває, спасається. Бо кожен, хто призве ім'я Господнє, спасеться (а хто не призиває, не спасеться)."],"h":"У скорботі призвав я Господа, і Він вислухав мене й вивів на простір"},{"v":"6","t":["Ці слова подібні до сказаних Давидом у 26-му псалмі: Господь — просвітлення моє й Спаситель мій, кого мені боятися? Тут зауваж, читачу, що Давид не сказав, що я не зазнаю від людини жодного зла, а що не злякаюся, хоч би й зазнав чогось. Бо те, що я зазнаю, не означає, що Бог безсилий, адже Він допомагає мені, а що Бог допустив цьому статися зі мною за мої гріхи для мого покарання й виправлення.","Прим.: Золотоустого: чи бачиш висоту духу? Чи бачиш, як розум його став вище людської немочі? Чи бачиш, з якої висоти дивиться він на всю природу? Це ми повинні не тільки просто співати, а й ділами здійснювати. Не сказав: нічого зі мною не станеться, а: не злякаюся, що зробить мені людина. І хоч станеться, не боюся, каже; це й Павло каже: а якщо Бог за нас, то хто проти нас?"],"h":"Господь мені помічник, і не злякаюся: що зробить мені людина?"},{"v":"7","t":["Бог, каже, воюватиме за мене, а я тільки дивитимуся на падіння й поразку моїх ворогів: на чуттєвих ворогів дивитимуся чуттєвими очима, а на мисленних — демонів — розумовими очима душі. Ці слова личать і всім, хто має безсумнівну надію на Господа."],"h":"Господь мені помічник, і я подивлюся на ворогів моїх"},{"v":"8-9","t":["Щасливий, каже, той, хто уповає на Господа, а не на людину; тому Єремія каже: проклятий той, хто надіється на людину (Єр. 17:5); і мудрий Сирах сказав: погляньте на давні роди й побачте: хто довірився Господеві й був посоромлений? (Сир. 2:10). А якщо когось надія обманює і він не дістає того, на що сподівався, то такий надіявся на Бога не так, як належить. Тому й Павло, підтверджуючи його слова, каже: а надія не засоромлює (Рим. 5:5). Давид сказав не в порівнянні, що краще надіятися на Бога, ніж на людину, бо не можна порівнювати перше з другим, а сказав так, пристосовуючись до немочі слухачів, як пояснює Золотоустий.","Прим.: Він так каже: не в порівнянні припускає це; бо надія на Господа — просто й у власному розумінні благо, а надія на людину — не благо. Бо немає нічого слабшого за цю надію; до того ж вона не тільки нікчемна, а й оманлива; це знають ті, хто, понадіявшись на людей, разом з ними й упав. А надія на Бога не тільки сильна, а й не підвладна падінню чи якомусь перевороту. Феодорита: Бог і благий, і людинолюбний, і бажає благ, і може виконати бажане, і має владу нетлінну; а люди і за природою тлінні, і в думках мінливі, і часто не бажають благ; а якщо інколи й бажають, не можуть протистояти тим, хто кривдить, а якщо й почнуть, то лише на час. Тож краще залишити допомогу з боку людей і просити допомоги в Бога."],"h":"Краще надіятися на Господа, ніж надіятися на людину. Краще уповати на Господа, ніж уповати на князів"},{"v":"10-11","t":["Усі, каже, народи, що живуть у Палестині, змовившись між собою, оточують мене з усіх боків, як рибалки обкидають рибу сітями; але я ім'ям Господнім покарав і переміг їх. Або народами називає різні полчища демонів; бо біси, часто збираючись усі, оточують праведника й воюють з ним, то лякаючи його, то всіляко спокушаючи. А повторюючи слова «оточили мене, і я протистояв їм», Давид цим показує, яку велику й дивовижну силу має ім'я Боже, яке визволяло Давида з неминучої й невідворотної біди від ворогів, що оточували його, а самих ворогів дивовижно вражало й карало.","Прим.: Ісихій під народами розуміє різні способи людського життя, бо в язичників різна мораль. Отже, праведника оточують і лихі, і грошолюбці, і заздрісні, і горді, і лицеміри, вважаючи його своїм спільним ворогом через те, що його добре життя їх викриває. Але він протистоїть безлічі їх ім'ям Божим: ім'я Його — Христос, і воно сильне для протистояння всякому задуму, бо стає для того, хто ним називається, і зброєю, і щитом, і твердинею. Феодорита: Церква зустріла напади всіх народів, а Єрусалим — не всіх, а деяких. Отже, ці слова суттєво стосуються Церкви. Бо віруючі з кожного народу зносили збурення й лиха від невіруючих, але, надіючись на Бога, перемогли противників."],"h":"Усі народи оточили мене, але ім'ям Господнім я протистояв їм. Обступаючи, оточили мене, але ім'ям Господнім я протистояв їм"},{"v":"12","t":["Цими словами Давид виражає, які великі були ті лиха, яких він зазнавав; порівнянням з бджолами зображує велику ревність, яку мали проти нього вороги, а порівнянням з вогнем — їхній нестримний гнів, за поясненням Золотоустого: бджоли, коли випадково знайдуть медовий стільник, з великою ревністю обсідають його й смокчуть медову рідину; а вогонь, коли впаде в терня, буває неприборканий.","Прим.: Золотоустий додає й таке: до того ж показує й швидкість їхньої загибелі. Бо як бджоли, коли, захищаючись, жалять, то, встромивши жало, помирають, так, каже, і вороги своєю злобою винищують самих себе. І як вогонь, зайнявшись у терні, не триває довго, а швидко зникає разом з речовиною, так і вони, напавши раптово, швидко згасають і гинуть. Слова неназваного автора: в алегоричному розумінні бджола, що виробляє мед і ліпить віск, — це Церква, яка вшанувала Божу премудрість; вона хоч і не міцна своєю силою, бо проповідь її полягає не в переконливих словах людської мудрості, але має жало в явленні духа й сили. Натомість єретики, хоч і подібні до бджіл, але не бджоли, а трутні, що мають тільки подобу бджіл; вони самі не роблять меду й не ліплять воскових комірок, а, поїдаючи мед, противляться бджолі — Церкві. Але Церква винищує їх ім'ям Господнім, мов жалом, і розтинає їх навпіл викривальною істиною."],"h":"Оточили мене, як бджоли стільник, і спалахнули, як вогонь у терні, але ім'ям Господнім я протистояв їм"},{"v":"13","t":["Мене, каже, відштовхнули вороги, і, похилившись, я ледве не впав, тобто був у небезпеці впасти; але Господь допоміг мені, щоб тим більше показати Свою силу й промисел: Він вирвав мене з самих уст смерті, де я був у цілковитому розпачі.","Прим.: Слова Ісихія: втягують нас усі помисли, схильні до хтивості, і, зрушивши нас з непохитного стояння в законі, роблять нас легкою здобиччю для бісів; але коли ми тверезі, тобто пильні, то Бог буде нашим заступником, бо Він може і зміцнити наші душі, і прогнати тих, хто хоче нас повалити."],"h":"Відштовхнутий, я похилився, щоб упасти, але Господь підхопив мене"},{"v":"14","t":["Господь, каже, — моя сила, і похвала, і слава моя, бо через Господа я в такій пошані й славі в усіх за те, що маю такого всесильного помічника. Або каже, що я співаю й прославляю Господа завжди за те, що Він був моїм Спасителем.","Прим.: Золотоустого: що таке «спів мій»? Слава моя, похвала моя, окраса моя, знаменитість моя. Бо не тільки визволяє від лих, а й робить світлими й знаменитими, даючи спасіння разом зі славою. Оріген каже, що «сила моя і спів мій — Господь» означає те, що в безстрашного мученика є голос; а слова «став мені на спасіння», за іншим тлумачем, означають, що Господь, стаючи Спасителем, не дістає початку буття, бо Він перебуває завжди й вічний, а стає Спасителем щодо тих, хто спасається; тому все, що кажеться про Христа, чим Він став, передбачає таку саму милість. Бо Він не став Богом, чи Словом, чи істиною, чи мудрістю, чи Сином, а мудрістю для нас — не просто ставши мудрістю, а так само й праведністю, і освяченням, і викупленням — для нас і щодо нас. Так Бог зробив Його Христом і Господом: Христом, тобто Царем і Священиком над тими, хто належить до Його царства, за кого Він приносить жертву й хто побажав бути Його рабами. І взагалі, коли так розумітимеш те, що кажеться про Нього, не впадеш у нечестя."],"h":"Сила моя і спів мій — Господь, і Він став мені на спасіння"},{"v":"15","t":["Тут слід мати на увазі спільне дієслово «став», тобто Господь став для мене голосом радості й спасіння, а ця радість і спасіння виражаються співом пісень в оселях праведних, бо дивне моє спасіння, звершене Богом, спонукало мене виразити співом цю даровану мені радість і спасіння. Або: я збуджений радістю й спасінням до прославлення Бога. А оселями праведних Давид, думаю, називає тут келії подвижників, що мали з'явитися після домобудівництва втілення, бо в цих оселях переважно співається й читається подвижниками Давидів Псалтир. Або оселями називає помісні церкви. Правиця ж, каже, Господня, тобто Його допомога й сприяння, звершила славну перемогу над моїми ворогами й склала славу торжества над ними. Ці слова і є тим голосом радості й спасіння, про який сказав вище, що він мав повторюватися в оселях праведних.","Прим.: Золотоустого: коли Бог звершує все, то ті, хто здобуває перемогу, радіють і торжествують, подвійно радіючи: по-перше, зі спасіння, по-друге, зі спасіння через Бога. Євсевія: у вищому ж значенні треба розуміти так, що тепер, після винищення мисленних ворогів, які час від часу переслідували народ Божий, і після настання миру та спорудження Божих осель, тобто Його церков, по всьому всесвіті справді чути вдячні голоси радості — не в якомусь іншому місці, а тільки в оселях праведних, тобто церквах Христових. Який же голос чути, тобто підноситься, у церквах, що радіють своєму спасінню? І які слова чути в тому голосі? «Правиця Господня явила силу» і так далі. А неназваний автор оселями називає ті оселі в Отця, про які сказав Спаситель: щоб, коли збіднієте (тобто помрете), прийняли вас вони (убогі, яким ви подавали милостиню) у вічні оселі. У цих оселях усі праведні радіють, бо досягли благ, на які чекали."],"h":"Голос радості й спасіння в оселях праведних: правиця Господня явила силу"},{"v":"16","t":["Правиця, каже, Божа підняла мене, що впав; або й прославила, як переможця моїх ворогів. Далі з радості повторює: правиця Господня явила силу, — щоб збільшити подяку Богові. Або, кажучи тричі «правиця Господня», таємниче виражає те, що він дістав від Триіпостасного Бога потрійну допомогу.","Прим.: Золотоустого: дивись, яка причина радості — та, що Бог звершив це. Чи бачиш, що Його благодіяння полягають не тільки у звільненні від лих, а й у здобутті знаменитості? Бо не тільки зробив їх сильними, а й славними. Ось і голос радості — сповідання, що одна сила Господня звершила перемогу, склала славу торжества над ними, спасла тих, хто подвизався, і піднесла їх. А правиця, за Феодоритом і Євсевієм, — це творення благ і Єдинородний Син Отця. А неназваний тлумач каже так: явно відкриває тут таїнство Трійці, назвавши правицю Господню тричі; бо так він розрізняє три Особи, адже вказав на три певні дії Божого промислу про нас. Так Він явив силу, коли взяв з землі порох і створив з нього людину за Своїм образом; явив ще силу, коли підніс її, і воскресив, і посадив разом з Собою на небесах Своєю правицею, як каже Павло; нарешті явив силу, коли без заслуг дарував їй Святого Духа. Його правиця, за поясненням іншого, являє силу над кожним, хто мислить і чинить право, і підносить його, так що буває й друга сила над ним — сила першої сили, через яку він, досягнувши безсмертя, скаже: не помру, а житиму."],"h":"Правиця Господня підняла мене, правиця Господня явила силу"},{"v":"17","t":["Отже, я, каже, не помру від ворогів, що оточили мене, як вони думали; ні, навпаки, вони помруть і загинуть, а я житиму й розповідатиму про Божі чудеса тим, хто не знав про них. Або каже, що я не зазнаю душевної смерті, а житиму в Бозі й буду безсмертний, бо всі пізніші праведники постійно співатимуть мої псалми й безперестанно читатимуть і співатимуть їх до кінця віку. Або в цих словах, за словами Євсевія, міститься пророцтво про майбутнє воскресіння Давида: я, каже, не помру так, щоб більше не встати, а знову житиму після воскресіння разом з усіма людьми; тому розповідатиму про діла Господні й разом з Його чудесами — і про даровано Ним воскресіння.","Прим.: Слова Євсевія: вислів «не помру», здається, вимовляють благочестиві, що час від часу страждали від гонінь з боку ворогів Церкви й наражалися на смерть; вони сміливо кажуть, що житимуть і дістануть додаток життя, щоб сповідувати діла Божі перед тими, хто бачив це на власні очі. Бо, за Золотоустим, особливо в тому й полягає життя, щоб хвалити Його й усім сповіщати Його чудеса й діла."],"h":"Не помру, а житиму й розповідатиму про діла Господні"},{"v":"18","t":["Господь, каже, покарав мене тим, що допустив мені зазнати лиха, щоб я став кращим і, виправившись страхом лиха й нужди, став розважливішим, ніж раніше; але Він не допустив мені померти, а визволив мене від смерті для того, як ми сказали вище, щоб показати, за поясненням Золотоустого, Свою силу й піклування про мене.","Прим.: Золотоустого: говорить про користь спокуси. У чому ж вона? У тому, що хоч, караючи, і покарав мене Господь, але через спокуси привів мене до кращого стану, так що я можу сповідувати, що те, що видавалося таким неприємним, обернулося мені на користь. Отже, він дістав подвійну користь: звільнився від лих і позбувся лихої вдачі. Тому й Павло в посланні каже: а якщо залишаєтеся без кари, то ви незаконні діти. Феодорита: з цих слів відкривається, що й саме гоніння на Церкву не було марним і випадковим, а для користі й випробування тих, хто зазнав спокус. Євсевія: той, кого карає Господь, посилаючи Своє божественне покарання єдино на його користь, стаючи через це визначним у способі думок і дій, не зазнає смерті, що панує над грішниками. Бо як смерть спіткає тих, хто залишається без кари, то він, як покараний Господом, не віддається смерті, що панує над відданими безчесним пристрастям і перекрученому розумові. Дидима: а чому Бог карає? Бо кого любить Господь, того й карає. З чого ж видно, що Він любить і тому карає праведника? З того, що не віддає його смерті; бо не допускає, щоб ворог переміг його на скорботу, а зі спокусою дає й полегшення. А карає Господь і тому, що, як каже Соломон, некарані душі впадають в оману (Прем. 17:1). А Феодорит каже, що допустив на мене сумні пригоди, караючи мене по-батьківськи, але цю темну хмару Він розвіяв і цілком звільнив мене від гіркоти, якою вони мені загрожували."],"h":"Караючи, покарав мене Господь, але смерті не віддав мене"},{"v":"19","t":["Відчиніть, каже, мені, священики й левити, брами скинії, у якій перебуває правда закону та його постанови, щоб я, увійшовши ними, міг дякувати Господеві й прославляти Його, як обіцяв раніше. Під брамами правди можна розуміти й оселі вищезгаданих подвижників і помісні церкви, у яких живе правда й усяка чеснота, щоб Давид, увійшовши ними, міг дякувати Господеві співом там своїх псалмів.","Прим.: Золотоустого: брами відчиняються тим, хто через покарання віддаляється від гріхів. Отже, хто покараний, той сміливо може казати: відчиніть мені брами правди. Бо ці слова слід розуміти у вищому значенні й під брамами розуміти небесні брами, які зачинені для лихих і в які треба стукати чеснотою, милостинею й правдою. Феодорита: у вищому значенні брамами правди називає різні види чесноти й успіх у них; ними входять ті, хто часом зносив скорботи. Євсевія: тож бачиш, що Бог доречно встановив, щоб ми йшли всякою дорогою чесноти, ніби різними брамами, за якими відчиняться для нас найостанніші й єдині, яких не можна обминути; а вони — бачення Бога, як сказано: блаженні чисті серцем, бо вони Бога побачать. Афанасій останніми й єдиними брамами називає Христа, Який сказав: Я — двері, як Наставника й Учителя чесноти. А Ісихій під брамами розуміє закон і пророків, а під дверима — віру, що приводить нас до Бога."],"h":"Відчиніть мені брами правди; увійшовши ними, прославлю Господа"},{"v":"20","t":["Думаю, що брамою Давид називає тут ту вузьку браму, про яку Господь сказав в Євангелії: входьте вузькою брамою (Мт. 7:13); тому й Давид, передбачаючи цю вузьку браму, сказав, що це брама Господня, про яку навчатиме Господь Ісус після Свого пришестя і яка веде людей до Господа. Він також додав, що праведні ввійдуть нею, тобто цією вузькою брамою. Тому й Господь сказав: і небагато тих, що знаходять її! (Мт. 7:14). Праведників і вибраних небагато тому, що, як Сам Він сказав, багато покликаних, а мало вибраних (Мт. 20:16).","Прим.: І Кирило під дверима розуміє Христа: бо неможливо іншим способом досягти пізнання Бога й Отця, як тільки тим, який указав Христос: ніхто не приходить до Отця, як тільки через Мене. Афанасія: ті, хто ходить дорогами чеснот, а краще — у чеснотах (бо в них треба вправлятися), входять у ті двері, що приводять до самого бачення Господа. Які ж це? Чистота серця: блаженні, каже, чисті серцем, бо вони Бога побачать. Золотоустого: є брами смерті, є брами погибелі, є брами життя — вузькі й скорботні. Отже, оскільки дверей багато, то показує ознаку дверей Господніх у тому, що ними входять покарані. Бо ті, хто зазнає скорбот, можуть увійти ними — не брамами смерті й погибелі й не широкою й просторою дорогою, бо такі дороги не Господні, а вузькою."],"h":"Це брама Господня, праведні ввійдуть нею"},{"v":"21","t":["І цими словами Давид обіцяє дякувати Богові за своє спасіння від лих, як обіцяв дякувати Йому й раніше."],"h":"Прославлю Тебе, бо Ти вислухав мене і став мені на спасіння"},{"v":"22","t":["Очевидно, це пророцтво про Христа; але воно не має тісного зв'язку з попередніми словами. Так пророцтва зазвичай переривають зв'язок мови й поміщаються між іншими словами, щоб у той час на них падала тінь і приховувала їх від юдеїв, аби юдеї, як вороги Христа, не знищили через них пророчих книг. Будівничими Давид називає, за словами Феодорита, юдейських архієреїв, книжників і вчителів, бо вони поставлені від Бога, щоб будувати й удосконалювати цей народ на основі закону; а відкинутим каменем називає Христа: каменем — через твердість і непохитність Його щодо гріха, бо беззаконня, каже Писання, Він не вчинив (Іс. 53:9); а відкинутим — бо юдейські архієреї й книжники відкинули й знехтували Ним, як непридатним для будови: вони казали, що Ти самарянин і біс у Тобі (Ін. 8:48); а також: цей чоловік не від Бога (Ін. 9:16); і ще: Він зводить народ.","А тим часом цей відкинутий ними камінь, тобто Христос, такий випробуваний і так виявився придатним для будови, що став наріжним каменем; бо не всякий камінь кладуть у кут, а тільки той, що більш випробуваний, твердіший і здатний зв'язувати дві стіни будівлі своїми двома боками в одному куті. Як же Христос став наріжним каменем? Поєднавши два народи — юдейський і язичницький — однією вірою; тому й Павло каже: Христос — мир наш, що зробив з обох одне (Еф. 2:14); і Сам Господь сказав: є в Мене й інші вівці, що не з цієї кошари, і тих Мені треба привести, і голос Мій почують, і буде одна отара й один пастир (Ін. 10:16). Або кутом називає Церкву віруючих: бо як кут поєднує собою в одне ціле дві стіни, так і Христова Церква поєднує два народи — юдейський і язичницький; а голова її — Христос, як єдиного тіла, і не тільки голова її, а й зв'язок, і основа.","Прим.: Інший каже: це й раніше було, але тільки ніби в образі поставлено; бо Авраам був патріархом обох народів — і необрізаних, і обрізаних; то служило тільки образом, а це — самою справою. Богоносного Максима: Христос став головою кута, тобто поєднав з Собою два народи й став Головою Церкви. Бо, за словами Писання, кут — це Церква; адже як кут поєднує дві стіни, зв'язуючи їх взаємно в одну нероздільну цілість, так і Церква поєднує два народи — з язичників і юдеїв, з'єднуючи їх одним союзом віри й сполучаючи в один дух, наріжним каменем якого, як головою всього тіла, є Христос. Бо як зв'язком двох стін буває наріжний камінь, що зв'язує їх нероздільним союзом, так і домобудівництво втілення Владики, сполучивши в одну нову людину два народи всесвіту й склавши з них одне тіло й один дух, стало головою кута, зберігши Своїм посередництвом цю єдність непохитною. Феодорита: цих слів юдеї не можуть прикласти ні до кого іншого, хоч би тисячу разів виявляли своє безсоромство. Бо хоча після поділу колін у давнину й правив у них Зоровавель, але недовго. А Христос Господь стіни, що зовсім далеко стояли одна від одної, тобто тих, хто увірував з юдеїв і язичників, зібрав в одне й сполучив далеке однією вірою, і склав з обох одну Церкву й одну отару, Сам ніби уподібнившись наріжному каменеві, що зв'язує дві стіни й сполучає одну з одною. Про цей камінь Бог передрік і через Ісаю: ось Я кладу на Сіоні камінь дорогоцінний, вибраний, наріжний, чесний, в основу його. Те саме сказав і блаженний Павло: утверджені на основі апостолів і пророків, маючи Самого Ісуса Христа наріжним каменем. Цей камінь бачив і божественний Даниїл, як він відірвався без рук. І Сам Ісус Христос сказав ці слова Давида юдеям: хіба ви ніколи не читали в Писанні: камінь, який відкинули будівничі, той став головою кута? (Мт. 21:42)."],"h":"Камінь, який відкинули будівничі, той став головою кута"},{"v":"23","t":["Цей, каже, кут, ця єдність двох народів і цей союз сталися від Бога, а не від простої людини, і він дивний в очах наших, якими ми сподобилися його бачити. Бо як не дивна така велика й всемогутня справа?","Прим.: Золотоустого: хто не жахнеться? Хто не здивується тому, що там поклоняються Христові, де Його розп'яли? І ті, що розп'яли Його, — у безчесті, а ті, що поклоняються, — у славі. І це слово поширилося по всесвіту, сполучаючи своєю істиною всіх. Воно дивне й для тих, хто хоч трохи його досліджує, але набагато достовірніше для віруючих. Тому й додав: в очах наших. Бо ця справа не була людська й не була у владі когось із людей, і ні ангели, ні архангели не могли сполучити такого кута. Ніхто не міг — ні праведник, ні пророк, ні ангел, ні архангел — звершити це, а тільки Сам Бог. Це виключно Його діло. Неназваного автора: дивне в очах наших те, що Діва могла народити, Розіп'ятий воскрес і воскресив мертвих, що Той, Кого били по щоках і ганьбили, підкорив усесвіт. Хоча плоть у Нього від нас, але вона дістала буття від Господа — Отця. І все таїнство звершено силою Божества."],"h":"Від Господа це сталося, і дивне воно в очах наших"},{"v":"24","t":["Днем тут називає добробут і успіх. Бо як, за словами Орігена та Золотоустого, лихим днем називає не біг сонця, а ті нещастя, що сталися в нього, так, називаючи день добрим, ми цим указуємо на щасливі події впродовж нього. Тож і Давид пророкує тепер про славні діла, блага й перемоги, звершені Господом нашим Ісусом Христом у день воскресіння. Бо в цей день Христос примирив Бога з людьми, припинив лютість диявола, знищив силу смерті, недостойних і землі сподобив неба, розвіяв темряву омани, прогнав гріх, насадив чесноту й сповнив усесвіт іншими незліченними духовними благами; тому Давид і спонукає всіх, хто вірує в Христа, до радості й веселощів у цей день воскресіння, як тих, хто сподобився в нього таких духовних благ.","Прим.: Слова Афанасія: який це день, як не спасенний для всіх народів, у який відкинутий камінь став головою кута? Тобто день воскресіння Спасителя, названий так від Його імені — Господній, тобто неділя. Феодорита: іменує днем, створеним від Бога, той, у який цей Камінь устав після Свого страждання. Бо відразу після воскресіння звелів апостолам навчити всі народи. Бо інші дні освітлюються сонцем, і світло, що походить від нього, воно дає тілам, а не душам; а сяйво спасенного Слова осяває словесні душі; воно й склало новий день — день світла й благочестя для всього світу. Отже, хоча й кожен день Господній, але він каже, що цей день особливо створений благим Богом, бо в цей день і на початку Бог сотворив світло, і він же, вшанований воскресінням нашого Спасителя, осяявся промінням Сонця правди. До того ж і Творець світла назвав його днем, не сотворивши нічого іншого в цей день. Отже, цей один день прийняв створення світла й назву «день». Тому влучно сказав: це день, що його створив Господь. А інші кажуть допитливіше, що другий (понеділок) і третій (вівторок) дні тижня складало першостворене світло, яке створене першого дня (у неділю), а четвертий (середу), п'ятий (четвер), шостий (п'ятницю) і сьомий (суботу) творило сонце, створене в середу, четвертого дня. А перший день, тобто неділю, створив безпосередньо Сам Господь з нічого. Бо цей день був початком того року, у який Він створив небо й землю, як написано: на початку сотворив Бог небо й землю. Світло, що було першого дня, створене не відразу на самому його початку, тобто вранці, а, на думку богословів, через кілька годин. Бо, здається, минув певний час між творенням на початку Господнього дня неба й землі та всього, що між ними, і створенням у той день світла, як дає зрозуміти Писання такими словами: на початку сотворив Бог небо й землю; а земля була невидима й невлаштована, і темрява була над безоднею, і Дух Божий ширяв над водою; і сказав Бог: нехай буде світло. Бо вислів «ширяв» означає тривання часу. Феодорита: ти зрозумієш, що сказано в словах «це день, що його створив Господь», якщо вникнеш у те, що щодо світобудови першого дня не сказано, що Бог сотворив щось інше, крім самого цього дня: бо Бог сказав: нехай буде світло, і стало світло; і назвав Бог це світло днем. А веселощами тут називає, за Золотоустим, духовні, мисленні, розумні. Отже, радіймо й веселімося в нім, що ми дістали стільки благ. Бо й це немала досконалість — радіти благами, грати, веселитися, з насолодою приймати Божі благодіяння."],"h":"Це день, що його створив Господь, радіймо й веселімося в нім"},{"v":"25","t":["Господи, каже, спаси Твій християнський народ. Господи, дай Твоєму народові успіх у дорозі й віру в проповідь Твого Євангелія.","Прим.: Золотоустого: передбачаючи добробут усього світу й зміну всього на кращий стан і радіючи разом з тими, хто його досяг, Давид каже: Господи, спаси ж нарешті; Господи, дай же нарешті успіх у дорозі, тобто спаси тих, хто ним користується, щоб насичувалися благодаттю й приносили гідні плоди. Улаштуй їм дорогу легку, щоб, насолоджуючись цим щастям, вони не втратили таких благ. Дидима: спаси від зол, як-от від гріха й омани, і дай успіх у дорозі, роблячи для нас дорогу чеснот легкою."],"h":"О Господи, спаси ж! О Господи, поспіши ж!"},{"v":"26","t":["І в цих словах — пророцтво про Христа; бо Христос прийшов в ім'я Господнє, тобто прийшов від Господа і з сутності Господньої; тому й юдеям Він казав: Я прийшов в ім'я Отця Мого, і ви не приймаєте Мене (Ін. 5:43); і ще: Я від Бога вийшов і прийшов (Ін. 8:42). Або вислів «в ім'я Господнє» означає те саме, що «під іменем Божим», тобто прийшов, маючи на Собі ім'я Боже й будучи Богом.","Прим.: Феодорита: у цих словах показав, до кого стосується спів єрусалимських отроків. Бо ці отроки виголосили Владиці ці слова на викриття тих, хто обіцяв навчати про Бога й не хотів розуміти справжнього змісту Писання: тоді як книжники зневажливо називали Владику самарянином, отроки іменували Його Тим, Хто йде, і визнавали благословенним. У цьому ж пророцтві є й «осанна», бо слово «спаси ж» у єврейському Псалтирі виражене словом «осанна». Тому й Хреститель, наставляючи своїх учнів в істині, тими самими словами питав Господа: чи Ти Той, Хто має прийти, чи іншого нам чекати? Далі, будучи Господом, Він прийшов в ім'я Господнє, і, будучи благословенним, Він — Син Благословенного. Так і архієрей питав Його: чи Ти Син Благословенного? Він, справді, за словами Орігена, є Тим, Хто йде, — і самовладно, і під іменем Господнім; тоді як до Нього всі мужі й ангели приходили як раби Господні. Так, наприклад, кожен казав: так каже Господь, і Господь послав мене. Кирила: що означає «в ім'я Господнє»? Означає — в богогідній славі, пануванні й перевазі над усіма. Золотоустого: добре сказано й це: «Хто йде»; бо наші справи не зупинилися на тому, що зроблено, а ще сягають інших, численніших, як-от воскресіння, царства, упокоєння з Христом; бажаючи все це виразити, сказав: благословенний, Хто йде в ім'я Господнє. Те саме й Христос сказав юдеям: ви самі будете свідками того, що Я не богопротивник, коли побачите Того, Хто йде на хмарах, і виголосите на Мою похвалу ці слова, через що позбудетеся всякого виправдання. Неназваного автора: добре сказано «Хто йде», а не «Хто прийшов»; бо Він завжди приходить і являється людському родові (хоча й не в плоті) без руху й переходу (бо за божественною присутністю Він наповнює небо й землю), коли ми своїми властивостями й налаштуванням наближаємося до Нього або віддаляємося від Нього.","«Благословили ми вас з дому Господнього»","Вас, каже, словесні вихованці Христової Церкви, ми — пророки, що віруємо й знаємо такі таїнства щодо Христа, — благословили, називаючи вас, християн, як людей з дому Господнього, блаженними за те, що ви насолоджуватиметеся такими благами й божественними таїнствами; бо дім Господній — це Церква, що складається з віруючих.","Прим.: Золотоустого: явленням називає втілення й дивується, що Він, будучи Богом і Господом, і бувши таким за Своєю сутністю, сподобить нас Свого явлення. Тому ми, каже, і благословлятимемо Тебе за те, що дістали такий дар. На це й Христос указує, коли каже: багато пророків і праведників бажали бачити, що ви бачите, і не бачили, і чути, що ви чуєте, і не чули. Феодорит слова «з дому Господнього» пояснює так: ми несемо вам благословення того Каменя, Який став домом Бога Слова, що живе в Ньому; бо Слово, каже, стало плоттю й оселилося з нами."],"h":"Благословенний, хто йде в ім'я Господнє"},{"v":"27","t":["Христос, каже, — Бог, Христос — Господь, і Він явився людям через вочоловічення. Але замість майбутнього часу — «Бог Господь явиться нам» — сказано в минулому — «явився», за властивістю пророцтв, у яких майбутнє вживається як минуле.","Прим.: Феодорита: явно тут богослов'я про Владику Христа. Бо Кого вище назвав Каменем, потім — благословенним і Тим, Хто йде в ім'я Господнє, Того назвав і Господом, і Богом, і Тим, Хто явився в плоті й дарував спасіння віруючим. Орігена: Його пришестя означає не зміну місця, а явлення Того, Хто раніше був невидимий. Бо Слово, невидиме тому, що було образом невидимого Бога, прийнявши образ раба й ставши плоттю, явилося, щоб так, явившись, вести нас до бачення Своєї слави — слави як Єдинородного від Отця.","«Справляйте свято з густими гілками аж до рогів жертовника»","Один з тлумачів у Золотоустого замінює ці слова такими: святкуйте з тими, що покривають, тобто святкуйте жертвами, які покривають жертовник аж до його рогів. А інший: святкуйте з паростками, тобто вінками з квітів і гілками. Бо грецьке дієслово тут, за поясненням деяких, як-от Орігена, означає «покриваю», а на думку Дидима та інших — «розростаюся густо». Отже, цими словами Давид спонукає людей справляти світле свято, а нас, християн, — справляти свято духовними жертвами, які своїм множеством, вінцями чеснот і гілками добрих діл покривають таємничий жертовник душі.","Прим.: Феодорита: зберіться всі й, склавши найбільше свято, святкуйте своє спасіння так, щоб народ через своє множество тіснився й сягав аж до самого жертовника. Бо вислів, ужитий тут, поставлено в значенні тих, що юрмляться й від множества тиснуть одне одного, адже й зовнішні письменники тісне місце називають покритим натовпами. За словами Орігена, «покривальними» звуться херувими, що осінюють очищальник своїми крилами, бо це дієслово означає те саме, що покривати. У вищому значенні Григорій Ніський пояснює це так: усе творіння в Владики творіння — ніби якийсь царський палац; але оскільки через гріх, що ввійшов, уста тих, над ким запанувало зло, закрилися, і замовк голос радості, і розірвалася злагода тих, хто святкує, так що людська природа вже не святкувала разом з природою істот, що вища за світ, то явився Господь, щоб знову склалося одне злагоджене свято через прикрашення скинії дольнього творіння перед лицем найвищих і взірцевих сил, що разом торжествують довкола горішнього жертовника. Бо роги мисленного жертовника — це взірцеві й найвищі сили розумної природи, з якими людська природа, прикрашаючись оновленням тіл, сполучається й бере участь у святі, влаштувавши скинію, тобто оселю, під час воскресіння; бо це дієслово означає те саме, що прикрашатися або зодягатися, як пояснюють обізнані в цьому. Інший каже: жертовник Господній — це тіло. Бо як на жертовник клали всі жертви — і всепалення, і мирні жертви, і за гріхи, — так і тіло Христове приймає на себе всі наші всепалення й мирну жертву, тобто всю нашу чесноту, щоб освятити її, а понад те й жертви за гріхи, бо це Його тіло понесло наші гріхи. Отже, роги його — хрест; бо роги, каже, у руках Його (Ав. 3:4)."],"h":"Бог — Господь, і явився нам"},{"v":"28","t":["Ти, каже, Бог мій, і я, за словами Золотоустого, за це одне дякуватиму й прославлятиму Тебе, хоч би й не одержав від Тебе жодного благодіяння; бо творіння мають дякувати своєму Творцеві й за те, що Він створив їх і промишляє про них; але я завжди дякуватиму Тобі не тільки тому, що Ти Бог мій, а й тому, що Ти мій Благодійник; бо коли я просив Тебе, Ти вислухав мою молитву й спас мене від багатьох лих.","Прим.: Золотоустого: і без благодіянь, каже, слід дякувати Богові й прославляти Його за Його велич, буття й невимовну славу. Бо, сказавши про благодіяння, далі каже, що я й без того дякуватиму й сповідуватимуся за те, що маю такого Владику — такого високого, такого великого, такого невидимого, такого незбагненного. А слово «звеличу» означає те саме, що «славитиму»."],"h":"Ти Бог мій, і прославлю Тебе; Ти Бог мій, і звеличу Тебе; прославлю Тебе, бо Ти вислухав мене й став мені на спасіння"},{"v":"29","t":["За зауваженням Ісихія, тим самим віршем, яким почався цей псалом, він і закінчений; тому має вигляд кола, що закінчується в тій самій точці, з якої починається. Бо до чого цей псалом спонукає народ на початку, до того спонукає й наприкінці, тобто до сповідання перед Господом своїх гріхів, бо Він благий до тих, хто сповідається, і милість Його стала до тих, хто приносить покаяння. Або, за словами Дидима та Золотоустого, спонукає до подяки Господеві, бо Він благий до тих, хто вдячний Йому, і милість Його до них вічна.","Прим.: Золотоустого: він не вдовольняється тим, що сам приносить цю жертву, а кличе багатьох до спільної хвали й подяки й проповідує Боже людинолюбство, усюди оспівуючи його тривалість і величину; і це робить для того, щоб і ми були вдячні людинолюбному Богові, за словами того ж Золотоустого; для того, як вважає Ісихій, щоб ми все життя зберігали це сповідання (тобто гріхів); і, за словами Євсевія, для того, щоб, пам'ятаючи, яке спасіння нам дано, ми не відступали назад до ворога, бо це оберталося б нам на погибель."],"h":"Сповідуйтеся Господеві, бо Він благий, бо повік милість Його"}]};
